nction(selected)\010        value.talent,value.layout=selected,\"tree\"\010        local talent=info(value,spec);talentIcon:SetImage(talent and talent.icon);update()\010    end)\010    talentPicker:SetDisabled(#talentOrder==0)\010    talentPicker.configure=function() talentPicker:SetList(talents,talentOrder);talentPicker:SetValue(value.talent) end\010    parent:AddChild(addon:Widget_OperatorWidget(value,L[\"Points\"],update))\010",["kind"]="function",["line"]=58,["parameters"]={"parent","spec","value","update"}}},["hash"]="53ef92891c1c3ee3e5d5428c435bd9ed5a46f52f1e5a8df082c1b2220cea698a"},["Conditions/totem.lua"]={["bindings"]={["amount"]={["bindings"]={},["code"]="\010    return type(value.value)==\"number\" and value.value==value.value and value.value>=0 and value.value<math.huge\010        and type(value.operator)==\"string\" and addon.isin(addon.operators,value.operator)\010",["kind"]="function",["line"]=36,["parameters"]={"value"}},["color"]={["kind"]="value"},["element"]={["bindings"]={},["code"]="\010    return addon.IsConditionSpellID(value.spell) and value.spell<=4\010",["kind"]="function",["line"]=33,["parameters"]={"value"}},["findSpecific"]={["bindings"]={["observe"]="builtin:Conditions/totem.lua:observe",["platform"]="builtin:Conditions/totem.lua:platform",["remaining"]="builtin:Conditions/totem.lua:remaining"},["code"]="\010    local target,reason=observe(cache,platform.GetSpellInfo,value.spell)\010    if not target then return nil,reason end\010    local count,why=observe(cache,platform.GetTotemSlotCount)\010    if not count then return nil,why end\010    local unavailable\010    for slot=1,count do\010        local record,problem=observe(cache,platform.GetTotemInfo,slot)\010        if not record then unavailable=unavailable or problem or \"totem-data-unavailable\"\010        elseif record.active and remaining(record,start)>0 then\010            local matches=false\010            if value.ranked then\010                if record.spellID then matches=record.spellID==value.spell\010                elseif record.name==target.name or record.name==\"\" then unavailable=unavailable or \"totem-rank-unavailable\" end\010            else\010                matches=record.spellID==value.spell or record.name==target.name\010                if not matches and record.name==\"\" then\010                    local info,issue\010                    if record.spellID then info,issue=observe(cache,platform.GetSpellInfo,record.spellID) end\010                    if info then matches=info.name==target.name\010                    else unavailable=unavailable or issue or \"totem-identity-unavailable\" end\010                end\010            end\010            if matches and (not compareTime or addon.compare(value.operator,addon.round(remaining(record,start),3),value.value)) then return true end\010        end\010    end\010    if unavailable then return nil,unavailable end\010    return false\010",["kind"]="function",["line"]=43,["parameters"]={"value","cache","start","compareTime"}},["helpers"]={["kind"]="value"},["observe"]={["bindings"]={["platform"]="builtin:Conditions/totem.lua:platform"},["code"]="\010    return addon.getCached(cache,method,platform,...)\010",["kind"]="function",["line"]=26,["parameters"]={"cache","method","..."}},["platform"]={["kind"]="value"},["remaining"]={["bindings"]={},["code"]="\010    if not record.active then return 0 end\010    return math.max(0,record.startTime+record.duration-(start or GetTime()))\010",["kind"]="function",["line"]=29,["parameters"]={"record","start"}},["specific"]={["bindings"]={},["code"]="\010    return addon.IsConditionSpellID(value.spell) and (value.ranked==nil or type(value.ranked)==\"boolean\")\010",["kind"]="function",["line"]=40,["parameters"]={"value"}}},["hash"]="c1343dee26947ad16b61a990c3db7a171841466c5d2e3cb58938655b3e42c180"},["Conditions/weapon.lua"]={["bindings"]={["color"]={["kind"]="value"},["enchantObservation"]={["bindings"]={},["code"]="\010    if type(GetWeaponEnchantInfo)~=\"function\" then return nil,nil,nil,\"missing-api\" end\010    -- The protected cached API returns both hands' original tuple unchanged.\010    ---@diagnostic disable-next-line: unbalanced-assignments\010    local ok, main, mainExpires, mainCharges, _, off, offExpires, offCharges = pcall(addon.getCached, cache, GetWeaponEnchantInfo)\010    if not ok then return nil,nil,nil,\"api-error\" end\010    local enchanted, expires, charges=main,mainExpires,mainCharges\010    if value.offhand then enchanted,expires,charges=off,offExpires,offCharges end\010    if not addon.Platform:CanReadValue(enchanted) then return nil,nil,nil,\"restricted-value\" end\010    if enchanted==nil or enchanted==false or enchanted==0 then return false end\010    if enchanted~=true and enchanted~=1 then return nil,nil,nil,\"invalid-weapon-observation\" end\010    return true,expires,charges\010",["kind"]="function",["line"]=25,["parameters"]={"value","cache"}},["helpers"]={["kind"]="value"},["numericObservation"]={["bindings"]={},["code"]="\010    if not addon.Platform:CanReadValue(value) then return nil,\"restricted-value\" end\010    if type(value)~=\"number\" or value~=value or value<0 or value==math.huge then return nil,\"invalid-weapon-observation\" end\010    return value\010",["kind"]="function",["line"]=38,["parameters"]={"value"}},["swingSpeed"]={["bindings"]={["numericObservation"]="builtin:Conditions/weapon.lua:numericObservation"},["code"]="\010    if type(UnitAttackSpeed)~=\"function\" then return nil,\"missing-api\" end\010    -- pcall forwards the mainhand and offhand speeds from the observation.\010    ---@diagnostic disable-next-line: unbalanced-assignments\010    local ok,main,off=pcall(addon.getCached,cache,UnitAttackSpeed,\"player\")\010    if not ok then return nil,\"api-error\" end\010    local speed=main;if value.offhand then speed=off end\010    return numericObservation(speed)\010",["kind"]="function",["line"]=43,["parameters"]={"value","cache"}}},["hash"]="5f87a0286e3b360fecaf2e34a7ec014dca86a86748b53a40d403f8fb3da6cffc"},["Core/class_group_conditions.lua"]={["bindings"]={["GetClassGroupCount"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"},{["description"]="Evaluation-pass cache, or nil for fresh observations.",["name"]="cache",["type"]="table | nil"},{["description"]="Nonempty class filename token to count; no class-token whitelist is applied.",["name"]="class",["type"]="string"},{["description"]="True permits the raid roster when raid membership is known true; false or nil uses the solo or party roster.",["name"]="raid",["type"]="boolean | nil"}},["bindings"]={},["callName"]="addon:GetClassGroupCount",["code"]="\010    local platform=self.Platform\010    if not platform:CanReadValue(class) or not platform:CanReadValue(raid) then return nil,'restricted-value' end\010    if type(class)~='string' or class=='' then return nil,'invalid-class-group-query' end\010    if raid~=nil and type(raid)~='boolean' then return nil,'invalid-class-group-query' end\010    local grouped,reason=self.Functions.cache.getCached(cache,platform.GetGroupMembership,platform,false)\010    if grouped==nil then return nil,reason end\010    local prefix,size='party',4\010    if grouped and raid then\010        local inRaid,why=self.Functions.cache.getCached(cache,platform.GetGroupMembership,platform,true)\010        if inRaid==nil then return nil,why end\010        if inRaid then prefix,size='raid',40 end\010    end\010    local count=0\010    if not grouped or prefix=='party' then\010        local player,why=self.Functions.cache.getCached(cache,platform.GetRosterClassObservation,platform,'player')\010        if player==nil then return nil,why end\010        if player==class then count=1 end\010        if not grouped then return count end\010    end\010    for index=1,size do\010        local observed,why=self.Functions.cache.getCached(cache,platform.GetRosterClassObservation,platform,prefix..tostring(index))\010        if observed==nil then return nil,why end\010        if observed==class then count=count+1 end\010    end\010    return count\010",["description"]="Count matching class tokens in the current fixed roster. Read group membership first; when requested, raid membership selects raid1 through raid40 without a separate player fact. Solo and party paths read player first, then party1 through party4 when grouped. A complete known roster returns a count, including zero; any required unavailable fact returns nil with a reason. Complete observations share the evaluation-pass cache; no player class persists across passes. Archived raw callbacks retain their original load-time class separately.",["kind"]="function",["line"]=6,["parameters"]={"self","cache","class","raid"},["returns"]={{["description"]="Complete matching class count, including zero, or nil when unavailable.",["type"]="number | nil"},{["description"]="Validation, policy or required-fact availability reason for a nil count.",["type"]="string | nil"}}}},["hash"]="7e5e513b91d2eb8f1ee7d0ed1498f125993417e5a76c2dd066091b567528974a"},["Core/health_forecast_conditions.lua"]={["bindings"]={["GetConditionHealthForecast"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"},{["description"]="Selected unit token, unchanged in observations.",["name"]="unit",["type"]="string"},{["description"]="Absolute health target (negative means deficit) or percentage fraction.",["name"]="healthTarget",["type"]="number"},{["description"]="True selects percentage target and optional fresh provider facts.",["name"]="percentage",["type"]="boolean"},{["description"]="noheals selects damage only; nodmg selects healing only; other readable values select both.",["name"]="mode",["type"]="any"},{["description"]="Evaluation-pass native observation cache; nil queries afresh.",["name"]="cache",["type"]="table | nil"}},["bindings"]={["finite"]="builtin:Core/health_forecast_conditions.lua:finite",["nativeValue"]="builtin:Core/health_forecast_conditions.lua:nativeValue",["readField"]="builtin:Core/health_forecast_conditions.lua:readField"},["callName"]="addon:GetConditionHealthForecast",["code"]="\010    local platform=self.Platform\010    if platform:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not platform:CanReadValue(unit) or not platform:CanReadValue(percentage) or not platform:CanReadValue(cache) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' or type(percentage)~='boolean' then return nil,'invalid-health-forecast-query' end\010    if cache~=nil and type(cache)~='table' then return nil,'invalid-health-forecast-cache' end\010    if type(platform.GetHealthForecastIdentityObservation)~='function' then return nil,'missing-api' end\010    local guid,identityReason=addon.Functions.cache.getCached(cache,platform.GetHealthForecastIdentityObservation,platform,unit)\010    if not platform:CanReadValue(guid) then return nil,'restricted-value' end\010    if guid==nil then return nil,identityReason or 'unit-guid-unavailable' end\010    if guid==false then return false end\010    if type(guid)~='string' or guid=='' then return nil,'invalid-health-forecast-identity' end\010    local current,maximum\010    if percentage then\010        if type(platform.GetHealthForecastProviderObservation)~='function' then return nil,'missing-api' end\010        local provider,why=platform:GetHealthForecastProviderObservation(unit)\010        if not platform:CanReadValue(provider) then return nil,'restricted-value' end\010        if provider==nil then return nil,why or 'health-provider-unavailable' end\010        current,why=readField(platform,provider,'current')\010        if why then return nil,why end\010        maximum,why=readField(platform,provider,'maximum')\010        if why then return nil,why end\010        if current==nil or current==false then current,why=nativeValue(self,unit,'current',cache);if current==nil then return nil,why end end\010        if maximum==nil or maximum==false then maximum,why=nativeValue(self,unit,'maximum',cache);if maximum==nil then return nil,why end end\010    else\010        local why;current,why=nativeValue(self,unit,'current',cache)\010        if current==nil then return nil,why end\010    end\010    local valid,reason=finite(platform,current)\010    if not valid then return nil,reason end\010    if current<0 then return nil,'invalid-health-forecast-number' end\010    valid,reason=finite(platform,healthTarget)\010    if not valid then return nil,reason end\010    local target=healthTarget\010    if percentage then\010        valid,reason=finite(platform,maximum)\010        if not valid then return nil,reason end\010        if maximum<0 then return nil,'invalid-health-forecast-number' end\010        target=maximum*healthTarget\010    elseif healthTarget<0 then\010        local why;maximum,why=nativeValue(self,unit,'maximum',cache)\010        if maximum==nil then return nil,why end\010        target=target+maximum\010    end\010    valid,reason=finite(platform,target)\010    if not valid then return nil,reason end\010    if current==target then return 0 end\010    local history,why=readField(platform,self.damageHistory,guid)\010    if why then return nil,why end\010    if history==nil or history==false then return false end\010    if type(history)~='table' then return nil,'invalid-forecast-history' end\010    if not platform:CanReadValue(mode) then return nil,'restricted-value' end\010    local noheals,nodmg=mode=='noheals',mode=='nodmg'\010    local profile,profileReason=readField(platform,self.db,'profile')\010    if profileReason then return nil,profileReason end\010    local window,windowReason=readField(platform,profile,'damage_history')\010    if windowReason then return nil,windowReason end\010    valid,reason=finite(platform,window)\010    if not valid then return nil,reason end\010    if type(platform.GetHealthForecastTimeObservation)~='function' then return nil,'missing-api' end\010    local now,timeReason=platform:GetHealthForecastTimeObservation()\010    if not platform:CanReadValue(now) then return nil,'restricted-value' end\010    if now==nil then return nil,timeReason or 'forecast-time-unavailable' end\010    valid,reason=finite(platform,now)\010    if not valid then return nil,reason end\010    local functions=self.Functions.forecast\010    if type(functions)~='table' or type(functions.calculate)~='function' then return nil,'forecast-kernel-unavailable' end\010    local ok,rate,seconds,forecastReason=pcall(functions.calculate,platform,history,window,noheals,nodmg,now)\010    if not ok then return nil,'forecast-kernel-error' end\010    if not platform:CanReadValue(forecastReason) then return nil,'restricted-value' end\010    if forecastReason~=nil then return nil,forecastReason end\010    if not platform:CanReadValue(rate) then return nil,'restricted-value' end\010    if rate==nil or rate==false then return false end\010    valid,reason=finite(platform,rate)\010    if not valid then return nil,reason end\010    valid,reason=finite(platform,seconds)\010    if not valid then return nil,reason end\010    if seconds<=2 then return false end\010    local eta=0\010    local distance,divisor\010    if rate<0 and target<current then distance=current-target;divisor=-rate\010    elseif rate>0 and target>current then distance=target-current;divisor=rate end\010    if distance~=nil then\010        valid,reason=finite(platform,distance)\010        if not valid then return nil,reason end\010        eta=distance/divisor\010    end\010    valid,reason=finite(platform,eta)\010    if not valid then return nil,reason end\010    return eta\010",["description"]="Estimate time until selected health. Cache complete native identity and lazy scalar observations per evaluation pass, while provider, history, window, clock and forecast stay live. Exact target equality returns zero before history work. Preserve deliberate no-estimate false and initialized-zero results for zero or opposite rates; required invalid facts, overflow or 4096-unit work exhaustion are unavailable. Never mutate history or invent a partial estimate.",["kind"]="function",["line"]=30,["parameters"]={"self","unit","healthTarget","percentage","mode","cache"},["returns"]={{["description"]="Finite ETA including zero, false for known absence/no estimate, or nil when unavailable.",["type"]="number | boolean | nil"},{["description"]="Observation, history, work-limit or arithmetic availability reason.",["type"]="string | nil"}}},["finite"]={["bindings"]={},["code"]="\010    if not platform:CanReadValue(value) then return false,'restricted-value' end\010    if type(value)~='number' or value~=value or value>=math.huge or value<=-math.huge then return false,'invalid-health-forecast-number' end\010    return true\010",["kind"]="function",["line"]=3,["parameters"]={"platform","value"}},["nativeValue"]={["bindings"]={["finite"]="builtin:Core/health_forecast_conditions.lua:finite"},["code"]="\010    local platform=self.Platform\010    if type(platform.GetHealthForecastValueObservation)~='function' then return nil,'missing-api' end\010    local value,why=addon.Functions.cache.getCached(cache,platform.GetHealthForecastValueObservation,platform,unit,kind)\010    if not platform:CanReadValue(value) then return nil,'restricted-value' end\010    if value==nil then return nil,why or 'health-data-unavailable' end\010    local valid,reason=finite(platform,value)\010    if not valid then return nil,reason end\010    if value<0 then return nil,'invalid-health-forecast-number' end\010    return value\010",["kind"]="function",["line"]=18,["parameters"]={"self","unit","kind","cache"}},["readField"]={["bindings"]={},["code"]="\010    if not platform:CanReadValue(object) then return nil,'restricted-value' end\010    if type(object)~='table' then return nil,'invalid-health-forecast-data' end\010    local ok,value=pcall(function() return object[key] end)\010    if not ok then return nil,'health-forecast-data-error' end\010    if not platform:CanReadValue(value) then return nil,'restricted-value' end\010    return value\010",["kind"]="function",["line"]=9,["parameters"]={"platform","object","key"}}},["hash"]="a6516ccd115cb8cb994950701317f4ae6de98952221827bb8acc453958b3500f"},["Core/level_conditions.lua"]={["bindings"]={["GetConditionUnitLevel"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"},{["description"]="Unit token whose raw level should be resolved.",["name"]="unit",["type"]="string"},{["description"]="Shared evaluation cache; nil observes directly without a per-pass cache.",["name"]="cache",["type"]="table | nil"}},["bindings"]={},["callName"]="addon:GetConditionUnitLevel",["code"]="\010    if not self.Platform:CanReadValue(unit) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if self.Platform:GetClientInfo().family=='unknown' then return nil,'unsupported-client' end\010    local longterm=self.longtermCache\010    if unit=='player' and type(longterm)=='table' then\010        local level=longterm.conditionPlayerLevel\010        if not self.Platform:CanReadValue(level) then return nil,'restricted-value' end\010        if level~=nil then\010            if type(level)~='number' or level~=level or level<=0 or level==math.huge or level%1~=0 then return nil,'invalid-api-result' end\010            return level\010        end\010    end\010    local record,reason=addon.Functions.cache.getCached(cache,self.Platform.GetUnitLevelObservation,self.Platform,unit)\010    if not record then return nil,reason end\010    if not record.exists then return false end\010    if unit=='player' and type(longterm)=='table' then longterm.conditionPlayerLevel=record.level end\010    return record.level\010",["description"]="Resolve a readable raw unit level for condition evaluation. Known absence returns false; unavailable observations return nil with a reason. Cache observations within the supplied evaluation pass. Only valid player levels are retained between passes until a skill, profile or level refresh.",["kind"]="function",["line"]=5,["parameters"]={"self","unit","cache"},["returns"]={{["description"]="Positive integer level, false for a known absent unit, or nil when unavailable.",["type"]="number | boolean | nil"},{["description"]="Availability or query-validation reason for a nil level.",["type"]="string | nil"}}}},["hash"]="1be155302689f439a548f6233e1c6e97cb372248ef07c58f48bc99e2e313b520"},["Core/point_conditions.lua"]={["bindings"]={["GetConditionPointResource"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"},{["description"]="Exact selected unit token; player class alone may use the successful longterm cache.",["name"]="unit",["type"]="string"},{["description"]="Evaluation-pass cache, or nil to observe identity directly. Resource mapping is resolved live on each invocation.",["name"]="cache",["type"]="table | nil"}},["bindings"]={["playerClassCacheKey"]="builtin:Core/point_conditions.lua:playerClassCacheKey",["pointIdentity"]="builtin:Core/point_conditions.lua:pointIdentity"},["callName"]="addon:GetConditionPointResource",["code"]="\010    local platform=self.Platform\010    if platform:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not platform:CanReadValue(unit) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    local record,reason=addon.Functions.cache.getCached(cache,pointIdentity,self,unit,playerClassCacheKey)\010    if not record then return nil,reason end\010    if not record.exists then return false end\010    local points=self.points\010    if not platform:CanReadValue(points) then return nil,'restricted-value' end\010    if type(points)~='table' then return nil,'invalid-point-resource-map' end\010    local ok,selected=pcall(function() return points[record.class] end)\010    if not ok then return nil,'api-error' end\010    if not platform:CanReadValue(selected) then return nil,'restricted-value' end\010    if selected==nil or selected==false then\010        local enum=Enum\010        if not platform:CanReadValue(enum) then return nil,'restricted-value' end\010        if type(enum)~='table' then return nil,'point-resource-unavailable' end\010        local typesOK,types=pcall(function() return enum.PowerType end)\010        if not typesOK then return nil,'api-error' end\010        if not platform:CanReadValue(types) then return nil,'restricted-value' end\010        if type(types)~='table' then return nil,'point-resource-unavailable' end\010        local fallbackOK,fallback=pcall(function() return types.ComboPoints end)\010        if not fallbackOK then return nil,'api-error' end\010        selected=fallback\010        if not platform:CanReadValue(selected) then return nil,'restricted-value' end\010    end\010    if selected==nil then return nil,'point-resource-unavailable' end\010    if type(selected)~='number' or selected~=selected or selected<0 or selected==math.huge or selected%1~=0 then return nil,'invalid-point-resource' end\010    return selected\010",["description"]="Resolve the selected unit point-resource selector using the live class-to-resource map and ComboPoints fallback. Known absence returns false; unavailable required identity or selector data returns nil with a reason. Share complete identity observations within the evaluation pass. Only successful player class observations persist in the current longterm cache, tied to the native UnitClass identity; existence is refreshed each pass. This selects a resource without reading its current or maximum quantity.",["kind"]="function",["line"]=29,["parameters"]={"self","unit","cache"},["returns"]={{["description"]="Explicit nonnegative integer power selector, false for a known absent unit, or nil when required data is unavailable.",["type"]="number | boolean | nil"},{["description"]="Policy, query-validation or identity/selector availability reason for a nil selector.",["type"]="string | nil"}}},["playerClassCacheKey"]={["kind"]="value"},["pointIdentity"]={["bindings"]={},["code"]="\010    local platform=self.Platform\010    local nativeClass=UnitClass\010    local longterm=self.longtermCache\010    if not platform:CanReadValue(longterm) or type(longterm)~='table' then longterm=nil end\010    local class\010    if unit=='player' and longterm and platform:CanReadValue(nativeClass) and type(nativeClass)=='function' then\010        local entry=rawget(longterm,key)\010        if platform:CanReadValue(entry) and type(entry)=='table' then\010            local api,candidate=rawget(entry,'api'),rawget(entry,'class')\010            if platform:CanReadValue(api) and api==nativeClass and platform:CanReadValue(candidate) and type(candidate)=='string' and candidate~='' then class=candidate end\010        end\010    end\010    local record,reason=platform:GetUnitPointIdentityObservation(unit,class==nil)\010    if not record then return nil,reason end\010    if not record.exists then return record end\010    if class then record.class=class\010    elseif unit=='player' and longterm and type(nativeClass)=='function' and nativeClass==UnitClass then\010        rawset(longterm,key,{api=nativeClass,class=record.class})\010    end\010    return record\010",["kind"]="function",["line"]=6,["parameters"]={"self","unit","key"}}},["hash"]="a73ccb7333af632938b66fc00738e6b5dc713aa29e0896a544f608c6f98774a9"},["Functions/cache.lua"]={["bindings"]={["cacheHits"]={["bindingID"]="builtin:utils.lua:cacheHits",["description"]="Packaged helper from utils.lua.",["kind"]="value",["namespace"]="utils"},["cacheMisses"]={["bindingID"]="builtin:utils.lua:cacheMisses",["description"]="Packaged helper from utils.lua.",["kind"]="value",["namespace"]="utils"},["cachedResult"]={["bindingID"]="builtin:utils.lua:cachedResult",["description"]="Packaged helper from utils.lua.",["kind"]="value",["namespace"]="utils"},["getCached"]={["args"]={{["description"]="Evaluation cache, or nil to bypass caching.",["name"]="cache",["type"]="table | nil"},{["description"]="Function or global function name to call.",["name"]="func",["type"]="function | string"},{["description"]="Arguments forwarded unchanged; types, identity, arity and nil positions distinguish cache entries.",["name"]="...",["type"]="any"}},["bindingID"]="builtin:utils.lua:getCached",["bindings"]={["getCachedInternal"]="builtin:utils.lua:getCachedInternal"},["callName"]="Functions.cache.getCached",["code"]="\010    return getCachedInternal(cache, true, func, ...)\010",["compatibilityNamespaces"]={"utils"},["description"]="Call an observation once per cache and exact argument tuple, including nil results. Pass the evaluation cache to share observations within a recommendation cycle; nil cache calls directly.",["kind"]="function",["line"]=75,["namespace"]="Functions.cache",["parameters"]={"cache","func","..."},["returns"]={{["description"]="All original results, preserving nil positions and return count.",["type"]="..."}}},["getCachedInternal"]={["bindingID"]="builtin:utils.lua:getCachedInternal",["bindings"]={["_G"]="builtin:utils.lua:_G",["cacheHits"]="builtin:utils.lua:cacheHits",["cacheMisses"]="builtin:utils.lua:cacheMisses",["cachedResult"]="builtin:utils.lua:cachedResult",["nilArgument"]="builtin:utils.lua:nilArgument",["packResults"]="builtin:utils.lua:packResults"},["code"]="\010    if type(func) == 'string' then func = _G[func] end\010    if type(func) ~= 'function' then return end\010    if cache == nil then return func(...) end\010\010    -- Exact keys preserve argument types, identity and arity. Hashing concatenated\010    -- strings allowed unrelated