forwarded unchanged to the observed function.",["name"]="...",["type"]="any"}},["bindingID"]="builtin:utils.lua:getRetryCached",["bindings"]={["getCachedInternal"]="builtin:utils.lua:getCachedInternal"},["callName"]="Functions.cache.getRetryCached",["code"]="\010    return getCachedInternal(cache, false, func, ...)\010",["compatibilityNamespaces"]={"utils"},["description"]="Cache an observation after it returns a non-nil value; retry observations whose entire return tuple is nil. Uses the same exact argument keys as getCached.",["kind"]="function",["line"]=79,["namespace"]="Functions.cache",["parameters"]={"cache","func","..."},["returns"]={{["description"]="All original results, preserving nil positions and return count.",["type"]="..."}}},["nilArgument"]={["bindingID"]="builtin:utils.lua:nilArgument",["description"]="Packaged helper from utils.lua.",["kind"]="value",["namespace"]="utils"},["packResults"]={["bindingID"]="builtin:utils.lua:packResults",["bindings"]={},["code"]="\010    return { n = select('#', ...), ... }\010",["description"]="Packaged helper from utils.lua.",["kind"]="function",["line"]=21,["namespace"]="utils",["parameters"]={"..."}},["protectedRead"]={["bindingID"]="builtin:Conditions/spatial.lua:protectedRead",["bindings"]={},["code"]="\010    if type(method)~=\"function\" then return false,\"missing-api\" end\010    return pcall(addon.getCached,cache,method,...)\010",["description"]="Packaged helper from Conditions/spatial.lua.",["kind"]="function",["line"]=4,["namespace"]="Conditions.spatial",["parameters"]={"cache","method","..."}}},["hash"]="75b13ab5ebf715adf2c7ce60977d5ad31321ecb83375817211c03b65533363cb"},["Functions/collections.lua"]={["bindings"]={["cleanArray"]={["args"]={{["description"]="Table to modify, or nil to do nothing.",["name"]="array",["type"]="table | nil"},{["description"]="Optional collection of key values selecting entries; its own keys are ignored.",["name"]="except",["type"]="table | nil"},{["description"]="True removes