iption"]="True when every visited entry compares equal in both directions.",["type"]="boolean"}}},["deepcopy"]={["args"]={{["description"]="Table to copy shallowly, or nil.",["name"]="array",["type"]="table | nil"},{["description"]="Optional collection of key values selecting entries; its own keys are ignored.",["name"]="except",["type"]="table | nil"},{["description"]="True includes only listed entries; false or nil excludes listed entries.",["name"]="invert",["type"]="boolean | nil"}},["bindings"]={},["callName"]="Functions.collections.deepcopy",["code"]="\010    if array == nil then\010        return nil\010    end\010    if invert == nil then\010        invert = false\010    end\010\010    local rv = {}\010    for k,v in pairs(array) do\010        local skip = invert\010        if except ~= nil then\010            for _,v2 in pairs(except) do\010                if (k == v2) then\010                    skip = not invert\010                    break\010                end\010            end\010        end\010        if not skip then\010            rv[k] = v\010        end\010    end\010    return rv\010",["description"]="Create a shallow filtered copy despite the historical deepcopy name. Nested values retain their original identities and the source metatable is not copied. By default exclude keys listed among except values; invert true includes only listed keys. Nil input returns nil.",["kind"]="function",["line"]=97,["parameters"]={"array","except","invert"},["returns"]={{["description"]="New shallow filtered table, or nil for nil input.",["type"]="table | nil"}}},["index"]={["args"]={{["description"]="Table to search; nil or false returns nil.",["name"]="array",["type"]="table | nil | false"},{["description"]="Value compared with each table value using Lua equality.",["name"]="value",["type"]="any"}},["bindings"]={},["callName"]="Functions.collections.index",["code"]="\010    if not array then return nil end\010\010    for idx,v in pairs(array) do\010        if (v == value) then\010            return idx\010        end\010    end\010",["description"]="Return the first key whose value equals the supplied value during pairs traversal. Nil or false input tables and absent values return nil. Multiple matching keys have no guaranteed selection order.",["kind"]="function",["line"]=50,["parameters"]={"array","value"},["returns"]={{["description"]="Matching key, including a false key, or nil when no match exists.",["type"]="any"}}},["keys"]={["args"]={{["description"]="Table whose values must be mutually comparable.",["name"]="array",["type"]="table"}},["bindings"]={},["callName"]="Functions.collections.keys",["code"]="\010    local rv = {}\010    for k,_ in pairs(array) do\010        table.insert(rv, k)\010    end\010    -- Sort the keys\010    table.sort(rv, function (lhs, rhs) return array[lhs] < array[rhs] end)\010    return rv\010",["description"]="Collect table keys and sort them by their associated values using Lua less-than comparison. This sorts values rather than key names; equal values have no guaranteed key order.",["kind"]="function",["line"]=9,["parameters"]={"array"},["returns"]={{["description"]="Dense array of keys sorted by associated value.",["type"]="table"}}},["multiinsert"]={["args"]={{["description"]="Destination array modified in place.",["name"]="t",["type"]="table"},{["description"]="Source array whose ipairs prefix is inserted without copying nested values.",["name"]="values",["type"]="table"}},["bindings"]={},["callName"]="Functions.collections.multiinsert",["code"]="\010    for i,v in ipairs(values) do\010\009    table.insert(t, i, v)\010    end\010",["description"]="Insert each value visited by ipairs at its corresponding leading index in the destination array. Existing entries shift after the inserted prefix; traversal stops at the first missing source index.",["kind"]="function",["line"]=67,["parameters"]={"t","values"},["returns"]={{["description"]="No return values. The destination array is modified in place.",["type"]="..."}}},["spairs"]={["args"]={{["description"]="Table to traverse; keys must be mutually comparable when no custom ordering is supplied.",["name"]="t",["type"]="table"},{["description"]="Optional ordering callback called as order(t, leftKey, rightKey).",["name"]="order",["type"]="function | nil"}},["bindings"]={},["callName"]="Functions.collections.spairs",["code"]="\010    -- collect the keys\010    local keys = {}\010    for k in pairs(t) do keys[#keys+1] = k end\010\010    -- if order function given, sort by it by passing the table and keys a, b,\010    -- otherwise just sort the keys\010    if order then\010        table.sort(keys, function(a,b) return order(t, a, b) end)\010    else\010        table.sort(keys)\010    end\010\010    -- return the iterator function\010    local i = 0\010    return function()\010        i = i + 1\010        if keys[i] then\010            return keys[i], t[keys[i]]\010        end\010    end\010",["description"]="Create an iterator over a sorted snapshot of table keys. Default ordering compares keys; a custom order callback receives the original table and two keys. Values are read from the original table when each key is yielded. The legacy iterator ends when the next captured key is nil or false.",["kind"]="function",["line"]=19,["parameters"]={"t","order"},["returns"]={{["description"]="Iterator yielding a captured key and its current table value, or no values when exhausted.",["type"]="function"}}},["tablelength"]={["args"]={{["description"]="Table to count, or nil for zero.",["name"]="T",["type"]="table | nil"}},["bindings"]={},["callName"]="Functions.collections.tablelength",["code"]="\010    if T == nil then return 0 end\010    local count = 0\010    for _ in pairs(T) do count = count + 1 end\010    return count\010",["description"]="Count all entries visited by pairs, including false values and sparse numeric or nonnumeric keys. A nil table has length zero.",["kind"]="function",["line"]=60,["parameters"]={"T"},["returns"]={{["description"]="Number of entries visited.",["type"]="number"}}},["tomap"]={["args"]={{["description"]="Table whose keys should be converted to strings.",["name"]="array",["type"]="table"}},["bindings"]={},["callName"]="Functions.collections.tomap",["code"]="\010    local rv = {}\010    for k,v in pairs(array) do\010        rv[tostring(k)] = v\010    end\010    return rv\010",["description"]="Copy a table using tostring of each original key as the destination key. Values retain their original identities. Colliding stringified keys overwrite each other in unspecified pairs traversal order.",["kind"]="function",["line"]=42,["parameters"]={"array"},["returns"]={{["description"]="New table with stringified keys and unchanged values.",["type"]="table"}}}},["hash"]="e9ed1b575966e47176fca5fcdbde98db736f5239b9ec0bac808c8e52285892dd"},["Functions/forecast.lua"]={["bindings"]={["Forecast_calculate"]={["args"]={{["description"]="Readability authority for consumed values.",["name"]="platform",["type"]="RMPlatform"},{["description"]="Damage/heals arrays of time/value rows; only selected streams are consumed.",["name"]="history",["type"]="table"},{["description"]="Explicit finite weighting window; no profile fallback or clamp.",["name"]="window",["type"]="number"},{["description"]="True skips all access to the healing stream.",["name"]="noheals",["type"]="boolean"},{["description"]="True skips all access to the damage stream.",["name"]="nodmg",["type"]="boolean"},{["description"]="Explicit finite clock snapshot; signed and fractional values remain valid.",["name"]="now",["type"]="number"}},["bindings"]={["finite"]="builtin:Functions/forecast.lua:finite",["readField"]="builtin:Functions/forecast.lua:readField"},["callName"]="Functions.forecast.calculate",["code"]="\010    if type(platform)~='table' or type(platform.CanReadValue)~='function' then return nil,nil,'invalid-forecast-platform' end\010    if not platform:CanReadValue(history) or not platform:CanReadValue(noheals) or not platform:CanReadValue(nodmg) then return nil,nil,'restricted-value' end\010    if type(history)~='table' then return nil,nil,'invalid-forecast-history' end\010    if type(noheals)~='boolean' or type(nodmg)~='boolean' then return nil,nil,'invalid-forecast-mode' end\010    local valid,reason=finite(platform,window)\010    if not valid then return nil,nil,reason end\010    valid,reason=finite(platform,now)\010    if not valid then return nil,nil,reason end\010    local work=0\010    local function scan(name,skip)\010        if skip then return 0,0,0 end\010        local rows,why=readField(platform,history,name)\010        if why then return nil,nil,nil,why end\010        if type(rows)~='table' then return nil,nil,nil,'invalid-forecast-stream' end\010        local maxoffs,data=0,{}\010        for _,row in ipairs(rows) do\010            work=work+1\010            if work>4096 then return nil,nil,nil,'forecast-work-budget' end\010            local time,problem=readField(platform,row,'time')\010            if problem then return nil,nil,nil,problem end\010            local good,numberReason=finite(platform,time)\010            if not good then return nil,nil,nil,numberReason end\010            local diff=now-time\010            good,numberReason=finite(platform,diff)\010            if not good then return nil,nil,nil,numberReason end\010            local scale=window-diff\010            local functions,namespaceReason=readField(platform,addon,'Functions')\010            if namespaceReason then return nil,nil,nil,namespaceReason end\010            if type(functions)~='table' then return nil,nil,nil,'forecast-round-unavailable' end\010            local values\010            values,namespaceReason=readField(platform,functions,'values')\010            if namespaceReason then return nil,nil,nil,namespaceReason end\010            if type(values)~='table' then return nil,nil,nil,'forecast-round-unavailable' end\010            local round\010            round,namespaceReason=readField(platform,values,'round')\010            if namespaceReason then return nil,nil,nil,namespaceReason end\010            if type(round)~='function' then return nil,nil,nil,'forecast-round-unavailable' end\010            local ok,rounded=pcall(round,diff)\010            if not ok then return nil,nil,nil,'forecast-round-error' end\010            good,numberReason=finite(platform,rounded)\010            if not good then return nil,nil,nil,numberReason end\010            maxoffs=rounded\010            if maxoffs>window then break end\010            local amount,amountReason=readField(platform,row,'value')\010            if amountReason then return nil,nil,nil,amountReason end\010            if amount~=nil and amount~=false then\010                good,numberReason=finite(platform,amount)\010                if not good then return nil,nil,nil,numberReason end\010                good,numberReason=finite(platform,scale)\010                if not good then return nil,nil,nil,numberReason end\010                local product=amount*scale\010                good,numberReason=finite(platform,product)\010                if not good then return nil,nil,nil,numberReason end\010                local value=(data[maxoffs] or 0)+product\010                good,numberReason=finite(platform,value)\010                if not good then return nil,nil,nil,numberReason end\010                data[maxoffs]=value\010            end\010        end\010        local bins=maxoffs<0 and 0 or math.floor(maxoffs)+1\010        if bins>4096-work then return nil,nil,nil,'forecast-work-budget' end\010        work=work+bins\010        local total,count=0,0\010        for i=0,maxoffs do\010            total=total+(data[i] or 0)\010            local good,numberReason=finite(platform,total)\010            if not good then return nil,nil,nil,numberReason end\010            local scale=window-i\010            good,numberReason=finite(platform,scale)\010            if not good then return nil,nil,nil,numberReason end\010            count=count+scale\010            good,numberReason=finite(platform,count)\010            if not good then return nil,nil,nil,numberReason end\010        end\010        return total,count,maxoffs\010    end\010    local damageTotal,damageCount,damageSeconds,damageReason=scan('damage',nodmg)\010    if damageReason then return nil,nil,damageReason end\010    local healTotal,healCount,healSeconds,healReason=scan('heals',noheals)\010    if healReason then return nil,nil,healReason end\010    local damageRate=damageCount>0 and -damageTotal/damageCount or 0\010    valid,reason=finite(platform,damageRate)\010    if not valid then return nil,nil,reason end\010    local healRate=healCount>0 and healTotal/healCount or 0\010    valid,reason=finite(platform,healRate)\010    if not valid then return nil,nil,reason end\010    local rate=damageRate+healRate\010    valid,reason=finite(platform,rate)\010    if not valid then return nil,nil,reason end\010    return rate,damageSeconds>healSeconds and damageSeconds or healSeconds\010",["description"]="Calculate a checked health-history rate using an explicit finite window and clock. Preserve ordered weighting, per-row live canonical rounding, skipped streams, array holes, fractional keys and final visited ages. A fixed 4096-unit budget covers visited rows and accumulation bins across both streams; excess or invalid consumed arithmetic returns unavailable, never a partial estimate or clamp. This new API has its own source identity; historical trend functions remain unchanged.",["kind"]="function",["line"]=23,["namespace"]="Functions.forecast",["parameters"]={"platform","history","window","noheals","nodmg","now"},["returns"]={{["description"]="Finite signed combined rate, or nil for unavailable calculation.",["type"]="number | nil"},{["description"]="Finite final stream age, or nil when unavailable.",["type"]="number | nil"},{["description"]="Work-limit, data or arithmetic availability reason for nil rate/age.",["type"]="string | nil"}}},["finite"]={["bindings"]={},["code"]="\010    if not platform:CanReadValue(value) then return false,'restricted-value' end\010    if type(value)~='number' or value~=value or value>=math.huge or value<=-math.huge then return false,'invalid-forecast-number' end\010    return true\010",["kind"]="function",["line"]=6,["parameters"]={"platform","value"}},["readField"]={["bindings"]={},["code"]="\010    if not platform:CanReadValue(object) then return nil,'restricted-value' end\010    if type(object)~='table' then return nil,'invalid-forecast-history' end\010    local ok,value=pcall(function() return object[key] end)\010    if not ok then return nil,'forecast-history-error' end\010    if not platform:CanReadValue(value) then return nil,'restricted-value' end\010    return value\010",["kind"]="function",["line"]=12,["parameters"]={"platform","object","key"}}},["hash"]="7db215bea2b1f69caa22156b4c940e3eeb78ae0657d05958cb9917ea807fc991"},["Functions/presentation.lua"]={["bindings"]={["compareString"]={["args"]={{["description"]="RM comparison operator identifier; missing labels use the operator placeholder.",["name"]="operator",["type"]="string | nil"},{["description"]="Text or number shown before the comparison wording.",["name"]="left",["type"]="string | number"},{["description"]="Text or number shown after the comparison wording.",["name"]="right",["type"]="string | number"},{["description"]="Mark the positive wording as the primary named alternative.",["name"]="primary",["type"]="boolean | nil"}},["bindingID"]="builtin:utils.lua:compareString",["bindings"]={["operators"]="builtin:Functions/presentation.lua:operators"},["callName"]="Functions.presentation.compareString",["code"]="\010    local positive=addon.nullable(operators[operator], L[\"<operator>\"])\010    local negative=(addon.negatedOperators or {})[operator]\010    local predicate=negative and ('{{'..(primary and '!' or '')..positive..'|'..negative..'}}') or positive\010    return left .. \" \" .. predicate .. \" \" .. right\010",["description"]="Format comparison wording with named Boolean alternatives when the operator has a negative form. The primary flag marks the positive form as the primary alternative. Positive operator labels use the captured operator map; negative labels and nullable dispatch retain their live addon APIs.",["kind"]="function",["line"]=41,["namespace"]="Functions.presentation",["parameters"]={"operator","left","right","primary"},["returns"]={{["description"]="Comparison text retaining named Boolean alternative markup.",["type"]="string"}}},["nullable"]={["args"]={{["description"]="Value to display; false is preserved.",["name"]="value",["type"]="any"},{["description"]="Missing-value display text; omitted uses the localized value placeholder.",["name"]="default",["type"]="string | nil"}},["bindingID"]="builtin:utils.lua:nullable",["bindings"]={["color"]="builtin:utils.lua:color"},["callName"]="Functions.presentation.nullable",["code"]="\010    if value == nil then\010        if default ~= nil then\010            return color.RED .. default .. color.RESET\010        else\010            return color.RED .. L[\"<value>\"] .. color.RESET\010        end\010    end\010    return value\010",["compatibilityNamespaces"]={"utils"},["description"]="Return a present value unchanged, or a red display placeholder for nil. Use for readable condition labels, not as a boolean fallback.",["kind"]="function",["line"]=11,["namespace"]="Functions.presentation",["parameters"]={"value","default"},["returns"]={{["description"]="Original non-nil value, or a colored placeholder string.",["type"]="any"}}},["nullable_value"]={["args"]={{["description"]="Key to look up.",["name"]="value",["type"]="any"},{["description"]="Display lookup table.",["name"]="array",["type"]="table | nil"},{["description"]="Missing-value display text; omitted uses the localized value placeholder.",["name"]="default",["type"]="string | nil"}},["bindingID"]="builtin:utils.lua:nullable_value",["bindings"]={["color"]="builtin:utils.lua:color"},["callName"]="Functions.presentation.nullable_value",["code"]="\010    if value == nil or array == nil or type(array) ~= \"table\" then\010        if default ~= nil then\010            return color.RED .. default .. color.RESET\010        else\010            return color.RED .. L[\"<value>\"] .. color.RESET\010        end\010    end\010    return addon.nullable(array[value], default)\010",["compatibilityNamespaces"]={"utils"},["description"]="Look up a table key for display, preserving non-nil results; invalid tables, missing keys and nil keys use nullable placeholder text.",["kind"]="function",["line"]=22,["namespace"]="Functions.presentation",["parameters"]={"value","array","default"},["returns"]={{["description"]="Original non-nil lookup result, or a colored placeholder string.",["type"]="any"}}},["operators"]={["kind"]="value"},["phrase"]={["args"]={{["description"]="Localized complete sentence with named slots and optional explicit predicate alternatives.",["name"]="template",["type"]="string"},{["description"]="Identifier-keyed scalar values or typed predicates. Strings, finite numbers and booleans are supported; referenced slots must be present. Values are captured when the phrase is created.",["name"]="values",["type"]="table"}},["bindings"]={},["callName"]="Functions.presentation.phrase",["code"]="\010    return addon:CreateConditionSummaryPhrase(template, values)\010",["description"]="Create a transient named condition summary. Use {name} for scalar values and {{positive|negative}} for predicate alternatives; prefix a primary alternative with !. Escape literal double braces as {{{{ and }}}}. Values are inserted literally without parsing their percent signs, links, colors or braces. Typed predicate values participate in primary selection. Templates, values and rendered text are bounded; malformed input renders a localized unavailable summary. This changes presentation only and runs no condition observations.",["kind"]="function",["line"]=49,["namespace"]="Functions.presentation",["parameters"]={"template","values"},["returns"]={{["description"]="Transient trusted phrase recognized by condition summary rendering; do not persist it as condition data.",["type"]="RMConditionPhrase"}}},["playerize"]={["args"]={{["description"]="Unit token to compare with the literal player token.",["name"]="unit",["type"]="string | nil"},{["description"]="Value returned when unit is player.",["name"]="player",["type"]="any"},{["description"]="Value returned for every other unit.",["name"]="nonplayer",["type"]="any"}},["bindingID"]="builtin:utils.lua:playerize",["bindings"]={},["callName"]="Functions.presentation.playerize",["code"]="\010    if (unit == \"player\") then\010        return player\010    else\010        return nonplayer\010    end\010",["description"]="Choose the supplied player value only for the literal player unit token; every other unit selects the nonplayer value. Selected false and nil values are preserved.",["kind"]="function",["line"]=33,["namespace"]="Functions.presentation",["parameters"]={"unit","player","nonplayer"},["returns"]={{["description"]="The selected value, including false or nil.",["type"]="any"}}},["predicate"]={["args"]={{["description"]="Comparison operator key, such as EQUALS or LESSTHAN.",["name"]="operator",["type"]="string"},{["description"]="True marks the main comparison to negate; false or nil leaves it eligible only when no primary predicate exists.",["name"]="primary",["type"]="boolean | nil"}},["bindings"]={["operators"]="builtin:Functions/presentation.lua:operators"},["callName"]="Functions.presentation.predicate",["code"]="\010    local positive=addon.nullable(operators[operator], L[\"<operator>\"])\010    return addon:CreateConditionSummaryPredicate(positive, (addon.negatedOperators or {})[operator], primary)\010",["description"]="Create a typed comparison predicate for a named condition phrase. Positive wording uses the original captured operator map and negative wording uses the current negated operator map. A primary predicate takes precedence over qualifiers; only the first eligible predicate negates. Unknown operators use the existing operator placeholder. This formats wording without comparing values or evaluating a condition.",["kind"]="function",["line"]=53,["namespace"]="Functions.presentation",["parameters"]={"operator","primary"},["returns"]={{["description"]="Transient typed predicate used as a named phrase value; do not persist it as condition data.",["type"]="RMConditionPredicate"}}}},["hash"]="0db5215bc1d3a16b8a1f63b66539b09261dceea9750d8d7ba12f68847e9dc279"},["Functions/text.lua"]={["bindings"]={["ends_with"]={["args"]={{["description"]="Text to inspect.",["name"]="str",["type"]="string"},{["description"]="Literal suffix, including an empty suffix.",["name"]="ending",["type"]="string"}},["bindings"]={},["callName"]="Functions.text.ends_with",["code"]="\010    return ending == \"\" or str:sub(-#ending) == ending\010",["description"]="Test a literal byte suffix using a Lua string slice. Empty suffixes match; pattern characters have no special meaning and case is preserved.",["kind"]="function",["line"]=42,["namespace"]="Functions.text",["parameters"]={"str","ending"},["returns"]={{["description"]="Whether the text ends with the exact suffix.",["type"]="boolean"}}},["split"]={["args"]={{["description"]="Text to split.",["name"]="inputstr",["type"]="string"},{["description"]="Lua pattern character-class separator, default %s for whitespace.",["name"]="sep",["type"]="string | nil"}},["bindingID"]="builtin:utils.lua:split",["bindings"]={["string"]="builtin:utils.lua:string"},["callName"]="Functions.text.split",["code"]="\010    if sep == nil then\010        sep = \"%s\"\010    end\010    local t={}\010    for str in string.gmatch(inputstr, \"([^\"..sep..\"]+)\") do\010        table.insert(t, str)\010    end\010    return t\010",["compatibilityNamespaces"]={"utils"},["description"]="Split a string into nonempty runs between separator characters. The separator is inserted into a Lua pattern character class; it is not a literal multi-character delimiter. Empty fields are omitted.",["kind"]="function",["line"]=9,["namespace"]="Functions.text",["parameters"]={"inputstr","sep"},["returns"]={{["description"]="Dense array of nonempty text fields.",["type"]="string[]"}}},["starts_with"]={["args"]={{["description"]="Text to inspect.",["name"]="str",["type"]="string"},{["description"]="Literal prefix, including an empty prefix.",["name"]="start",["type"]="string"}},["bindings"]={},["callName"]="Functions.text.starts_with",["code"]="\010    return str:sub(1, #start) == start\010",["description"]="Test a literal byte prefix using a Lua string slice. Empty prefixes match; pattern characters have no special meaning and case is preserved.",["kind"]="function",["line"]=38,["namespace"]="Functions.text",["parameters"]={"str","start"},["returns"]={{["description"]="Whether the text begins with the exact prefix.",["type"]="boolean"}}},["trim"]={["args"]={{["description"]="Text to trim.",["name"]="s",["type"]="string"}},["bindingID"]="builtin:utils.lua:trim",["bindings"]={},["callName"]="Functions.text.trim",["code"]="\010    return (s:gsub(\"^%s*(.-)%s*$\", \"%1\"))\010",["compatibilityNamespaces"]={"utils"},["description"]="Remove leading and trailing Lua-pattern whitespace from a string.",["kind"]="function",["line"]=34,["namespace"]="Functions.text",["parameters"]={"s"},["returns"]={{["description"]="Trimmed text.",["type"]="string"}}},["wrap"]={["args"]={{["description"]="Text to wrap.",["name"]="str",["type"]="string"},{["description"]="Target line width, default 72 characters.",["name"]="limit",["type"]="number | nil"}},["bindingID"]="builtin:utils.lua:wrap",["bindings"]={},["callName"]="Functions.text.wrap",["code"]="\010    limit = limit or 72\010    local here = 1\010\010    -- the \"\".. is there because :gsub returns multiple values\010    return \"\"..str:gsub(\"(%s+)()(%S+)()\",\010            function(_, st, word, fi)\010                if fi-here > limit then\010                    here = st\010                    return \"\\n\"..word\010                end\010            end)\010",["compatibilityNamespaces"]={"utils"},["description"]="Wrap text at whitespace boundaries near a target column count. Long words are retained intact.",["kind"]="function",["line"]=20,["namespace"]="Functions.text",["parameters"]={"str","limit"},["returns"]={{["description"]="Text with line breaks inserted at word boundaries.",["type"]="string"}}}},["hash"]="8ec672bad0bd626f087cec73e0158aede730609a864da2efcc416fd279ad4000"},["Functions/trends.lua"]={["bindings"]={["calculate"]={["args"]={{["description"]="History record with newest-first damage and heals arrays of time/value entries. Falsy history returns only zero without reading the clock.",["name"]="history",["type"]="table | false | nil"},{["description"]="Weighting window in seconds; nil or false uses the current profile damage_history setting.",["name"]="window",["type"]="number | false | nil"},{["description"]="Truthy skips the heals stream without reading its array.",["name"]="noheals",["type"]="boolean | nil"},{["description"]="Truthy skips the damage stream without reading its array.",["name"]="nodmg",["type"]="boolean | nil"}},["bindings"]={},["callName"]="Functions.trends.calculate",["code"]="\010    if not history then\010        return 0\010    end\010\010    if not window then\010        window = addon.db.profile.damage_history\010    end\010\010    local now = GetTime()\010    local damage_total, damage_count, damage_seconds = 0, 0, 0\010    local heal_total, heal_count, heal_seconds = 0, 0, 0\010\010    local maxoffs, data = 0, {}\010    if not nodmg then\010        for _,v in ipairs(history.damage) do\010            local diff = now - v.time\010            local scale = window - diff\010            maxoffs = addon.round(diff)\010            if maxoffs > window then\010                break\010            end\010\010            if v.value then\010                data[maxoffs] = (data[maxoffs] or 0) + (v.value * scale)\010            end\010        end\010        damage_seconds = maxoffs\010        for i=0,maxoffs do\010            damage_total = damage_total + (data[i] or 0)\010            damage_count = damage_count + (window - i)\010        end\010    end\010\010    if not noheals then\010        maxoffs, data = 0, {}\010        for _,v in ipairs(history.heals) do\010            local diff = now - v.time\010            local scale = window - diff\010            maxoffs = addon.round(diff)\010            if maxoffs > window then\010                break\010            end\010\010            if v.value then\010                data[maxoffs] = (data[maxoffs] or 0) + (v.value * scale)\010            end\010        end\010        heal_seconds = maxoffs\010        for i=0,maxoffs do\010            heal_total = heal_total + (data[i] or 0)\010            heal_count = heal_count + (window - i)\010        end\010    end\010\010    return (((damage_count > 0) and (-damage_total / damage_count) or 0) +\010           ((heal_count > 0) and (heal_total / heal_count) or 0)),\010           (damage_seconds > heal_seconds and damage_seconds or heal_seconds)\010",["description"]="Estimate signed health change from weighted damage and healing history. Damage contributes a negative rate and healing a positive rate. Read the live profile window when no window is supplied, use the live clock and legacy rounding service, and preserve the existing weighting and rounded-age calculation. This helper does not validate or sanitize history, clamp timestamps, or guarantee finite results.",["kind"]="function",["line"]=51,["namespace"]="Functions.trends",["parameters"]={"history","window","noheals","nodmg"},["returns"]={{["description"]="Combined signed weighted rate from the original formula; malformed or nonfinite inputs retain the legacy error/numeric behavior.",["type"]="number"},{["description"]="Larger rounded stream age in seconds, not a sample count or proof of continuous observation. Omitted when history is falsy.",["type"]="number | nil"}}},["calculateOld"]={["args"]={{["description"]="Newest-first health snapshots containing time, value and max. Falsy input returns only zero without reading the clock.",["name"]="health",["type"]="table | false | nil"}},["bindings"]={},["callName"]="Functions.trends.calculateOld",["code"]="\010    if not health then\010        return 0\010    end\010\010    local damage_history = addon.db.profile.damage_history\010    local now = GetTime()\010    local total, count, seconds = 0, 0, 0\010\010    local last_health, last_offs, last_max\010    local offs_total = 0\010    for _,v in ipairs(health) do\010        if v.value >= v.max or v.value == 0 then\010            break\010        end\010\010        if last_max ~= v.max then\010            last_health = nil\010            last_max = v.max\010        end\010\010        local offs = addon.round(now - v.time)\010        if last_health ~= nil then\010            offs_total = offs_total + (last_health - v.value)\010\010            if last_offs ~= offs then\010                local scale = damage_history - offs\010                count = count + scale\010                total = total + (offs_total * scale)\010                seconds = seconds + 1\010                offs_total = 0\010            end\010        end\010        last_health = v.value\010        last_offs = offs\010    end\010\010    if seconds then\010        return total / count, seconds\010    end\010    return 0\010",["description"]="Run the historical health-snapshot trend formula using the live profile history window, clock and legacy rounding service. Preserve its maximum-health transitions, early stop at full or zero health, weighting, errors and return counts. Empty snapshot arrays retain the original nonfinite result; this is the legacy algorithm rather than a validated forecast.",["kind"]="function",["line"]=8,["namespace"]="Functions.trends",["parameters"]={"health"},["returns"]={{["description"]="Weighted health-snapshot change from the original total/count formula; zero for falsy input.",["type"]="number"},{["description"]="Original rounded-age bucket count, omitted for falsy input.",["type"]="number | nil"}}}},["hash"]="eea1c3f5987e00a2f6855c02cb972ec8d88b7eff4a8a4f07d5d3f65e16a707de"},["Functions/values.lua"]={["bindings"]={["compare"]={["args"]={{["description"]="RM operator identifier.",["name"]="operator",["type"]="string"},{["description"]="Left operand; use numbers for ordering and divisibility.",["name"]="left",["type"]="any"},{["description"]="Right operand; DIVISIBLE requires a nonzero divisor.",["name"]="right",["type"]="any"}},["bindingID"]="builtin:utils.lua:compare",["bindings"]={},["callName"]="Functions.values.compare",["code"]="\010    if operator == \"LESSTHAN\" then\010        return left < right\010    elseif operator == \"LESSTHANOREQUALS\" then\010        return left <= right\010    elseif operator == \"GREATERTHAN\" then\010        return left > right\010    elseif operator == \"GREATERTHANOREQUALS\" then\010        return left >= right\010    elseif operator == \"EQUALS\" then\010        return left == right\010    elseif operator == \"NOTEQUALS\" then\010        return left ~= right\010    elseif operator == \"DIVISIBLE\" then\010        return (left % right) == 0\010    else\010        addon:warn(\"Invalid Operator %s\", operator)\010    end\010",["compatibilityNamespaces"]={"utils"},["description"]="Compare two values using an RM operator identifier: LESSTHAN, LESSTHANOREQUALS, GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS or DIVISIBLE. Invalid operators warn and return nil; operands must support the selected Lua operation.",["kind"]="function",["line"]=9,["namespace"]="Functions.values",["parameters"]={"operator","left","right"},["returns"]={{["description"]="Comparison result, or nil for an unknown operator.",["type"]="boolean | nil"}}},["floor"]={["kind"]="value"},["isin"]={["args"]={{["description"]="Table to inspect.",["name"]="array",["type"]="table"},{["description"]="Lookup key.",["name"]="value",["type"]="any"}},["bindingID"]="builtin:utils.lua:isin",["bindings"]={},["callName"]="Functions.values.isin",["code"]="\010    return array[value] ~= nil\010",["compatibilityNamespaces"]={"utils"},["description"]="Check whether a table has a non-nil value at a key. A stored false value still counts as present; this does not scan table values.",["kind"]="function",["line"]=29,["namespace"]="Functions.values",["parameters"]={"array","value"},["returns"]={{["description"]="True when array[value] is non-nil.",["type"]="boolean"}}},["isint"]={["args"]={{["description"]="Number or string to inspect; other types do not match.",["name"]="num",["type"]="any"}},["bindings"]={["floor"]="builtin:Functions/values.lua:floor"},["callName"]="Functions.values.isint",["code"]="\010    if type(num) == \"number\" then\010        return floor(num) == num\010    elseif type(num) == \"string\" then\010        local tmp = tonumber(num)\010        if tmp ~= nil then\010            return tostring(floor(tmp)) == num\010        end\010    end\010    return false\010",["description"]="Apply the legacy integer or canonical numeric-string spelling test. Numbers use floor equality; strings must equal the spelling obtained after numeric conversion and floor. Other types return false. This is not a finite-number validator.",["kind"]="function",["line"]=38,["namespace"]="Functions.values",["parameters"]={"num"},["returns"]={{["description"]="Whether the original floor-equality or exact numeric-spelling predicate matches.",["type"]="boolean"}}},["round"]={["args"]={{["description"]="Value passed to the original arithmetic formula.",["name"]="num",["type"]="number"},{["description"]="Decimal places, default zero; negative values round to tens or larger powers of ten.",["name"]="numDecimalPlaces",["type"]="number | nil"}},["bindings"]={["floor"]="builtin:Functions/values.lua:floor"},["callName"]="Functions.values.round",["code"]="\010    local mult = 10^(numDecimalPlaces or 0)\010    return floor(num * mult + 0.5) / mult\010",["description"]="Round with the existing floor(num * 10^places + 0.5) / 10^places formula. Places defaults to zero and may be negative. Halfway negative values round toward positive infinity; no finite-number validation or alternative rounding policy is added.",["kind"]="function",["line"]=33,["namespace"]="Functions.values",["parameters"]={"num","numDecimalPlaces"},["returns"]={{["description"]="One rounded numeric result from the original formula.",["type"]="number"}}}},["hash"]="63cf0de826be758a9e0e8963ea11824c80e28d2a40e6bdce200052f6cab760dc"},["Platform/actions.lua"]={["bindings"]={["Platform_GetSpellRangeState"]={["args"]={{["description"]="Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.",["name"]="self",["type"]="RMPlatform"},{["description"]="Spell ID whose range should be checked.",["name"]="id",["type"]="number"},{["description"]="Unit token, such as target; nil uses target.",["name"]="unit",["type"]="string | nil"},{["description"]="Spell-book scope: spell, pet or any.",["name"]="bank",["type"]="string"}},["bindings"]={["call"]="builtin:Platform/actions.lua:call",["findSlot"]="builtin:Platform/actions.lua:findSlot",["spellID"]="builtin:Platform/actions.lua:spellID"},["callName"]="addon.Platform:GetSpellRangeState",["code"]="\010    local valid,reason=spellID(id)\010    if not valid then return nil,reason end\010    if not self:CanReadValue(unit) or not self:CanReadValue(bank) then return nil,\"restricted-value\" end\010    if unit~=nil and (type(unit)~=\"string\" or unit==\"\") then return nil,\"invalid-unit\" end\010    if bank~=\"spell\" and bank~=\"pet\" and bank~=\"any\" then return nil,\"invalid-spell-bank\" end\010    unit=unit or \"target\"\010    local nativeRange=C_Spell and C_Spell.IsSpellInRange\010    local nativeShape=C_Spell and C_Spell.SpellHasRange\010    local slot,book,slotReason\010    local function legacySlot()\010        if not slot then slot,book,slotReason=findSlot(id,bank) end\010        return slot,slotReason\010    end\010    local hasRange,why,queriedShape\010    if type(nativeShape)==\"function\" then\010        queriedShape=true\010        hasRange,why=call(nativeShape,id)\010    elseif type(nativeRange)~=\"function\" and type(SpellHasRange)==\"function\" then\010        if not legacySlot() then return nil,slotReason end\010        queriedShape=true\010        hasRange,why=call(SpellHasRange,slot,book)\010    end\010    if why then return nil,why end\010    if hasRange~=nil then\010        if type(hasRange)~=\"boolean\" then return nil,\"invalid-api-result\" end\010        if not hasRange then return {applicable=false} end\010    elseif queriedShape then return nil,\"invalid-api-result\" end\010    local inRange\010    if type(nativeRange)==\"function\" then\010        inRange,why=call(nativeRange,id,unit)\010        if why then return nil,why end\010        if inRange~=nil and type(inRange)~=\"boolean\" then return nil,\"invalid-api-result\" end\010    else\010        if type(IsSpellInRange)~=\"function\" then return nil,\"missing-api\" end\010        if not legacySlot() then return nil,slotReason end\010        inRange,why=call(IsSpellInRange,slot,book,unit)\010        if why then return nil,why end\010        if inRange==0 then inRange=false elseif inRange==1 then inRange=true end\010        if inRange~=nil and type(inRange)~=\"boolean\" then return nil,\"invalid-api-result\" end\010    end\010    if inRange==nil then return nil,\"invalid-range-check\" end\010    return {applicable=true,inRange=inRange}\010",["description"]="Read spell-specific range for a unit using the appropriate client API or spell-book slot. A spell without a range restriction returns applicable=false; otherwise applicable=true and inRange records whether the unit is in range. Unknown or inaccessible observations return nil with a reason.",["kind"]="function",["line"]=40,["parameters"]={"self","id","unit","bank"},["returns"]={{["description"]="Range record with applicable and, when applicable, inRange; nil when unavailable.",["type"]="table | nil"},{["description"]="Availability or validation reason when the record is nil.",["type"]="string | nil"}}},["call"]={["bindings"]={["platform"]="builtin:Platform/actions.lua:platform"},["code"]="\010    if type(fn)~=\"function\" then return nil,\"missing-api\" end\010    local ok,value=pcall(fn,...)\010    if not ok then return nil,\"api-error\" end\010    if not platform:CanReadValue(value) then return nil,\"restricted-value\" end\010    return value\010",["kind"]="function",["line"]=9,["parameters"]={"fn","..."}},["findSlot"]={["bindings"]={["call"]="builtin:Platform/actions.lua:call"},["code"]="\010    local pet=bank==\"pet\"\010    local slot,reason=call(FindSpellBookSlotBySpellID,id,pet)\010    if reason then return nil,nil,reason end\010    if slot==nil and bank==\"any\" then\010        pet=true;slot,reason=call(FindSpellBookSlotBySpellID,id,true)\010        if reason then return nil,nil,reason end\010    end\010    if slot==nil then return nil,nil,\"spell-not-in-book\" end\010    if type(slot)~=\"number\" or slot<1 or slot==math.huge or slot%1~=0 then return nil,nil,\"invalid-api-result\" end\010    return slot,pet and (BOOKTYPE_PET or \"pet\") or (BOOKTYPE_SPELL or \"spell\")\010",["kind"]="function",["line"]=28,["parameters"]={"id","bank"}},["platform"]={["kind"]="value"},["spellID"]={["bindings"]={["platform"]="builtin:Platform/actions.lua:platform"},["code"]="\010    if not platform:CanReadValue(id) then return nil,\"restricted-value\" end\010    if type(id)~=\"number\" or id<1 or id==math.huge or id%1~=0 then return nil,\"invalid-spell\" end\010    return true\010",["kind"]="function",["line"]=4,["parameters"]={"id"}}},["hash"]="c540aab94ba6e7907539aee2a43bd4b3008fe7b7de63cf8d4a727af80e3732a2"},["Platform/casting.lua"]={["bindings"]={["Platform_GetUnitCastObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Unit token whose current cast or channel should be observed.",["name"]="unit",["type"]="string"},{["description"]="Observation kind: cast or channel. These use different native interruptibility tuple positions.",["name"]="kind",["type"]="string"}},["bindings"]={["interruptibility"]="builtin:Platform/casting.lua:interruptibility",["remainingSeconds"]="builtin:Platform/casting.lua:remainingSeconds"},["callName"]="addon.Platform:GetUnitCastObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) or not self:CanReadValue(kind) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if kind~='cast' and kind~='channel' then return nil,'invalid-cast-query' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local existsOk,exists=pcall(UnitExists,unit)\010    if not existsOk then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return {active=false} end\010    local fn\010    if kind=='cast' then fn=UnitCastingInfo else fn=UnitChannelInfo end\010    if type(fn)~='function' then return nil,'missing-api' end\010    -- Capture into an owned tuple table without comparing native values. The\010    -- channel flag is slot7; casting includes castID and uses slot8 instead.\010    local ok,tuple=pcall(function() return {fn(unit)} end)\010    if not ok then return nil,'api-error' end\010    local name=tuple[1]\010    if not self:CanReadValue(name) then return nil,'restricted-value' end\010    if name==nil then return {active=false} end\010    if type(name)~='string' or name=='' then return nil,'invalid-api-result' end\010    local record={active=true,name=name}\010    record.remainingSeconds,record.remainingReason=remainingSeconds(tuple[5])\010    record.interruptible,record.interruptibleReason=interruptibility(tuple[kind=='cast' and 8 or 7])\010    return record\010",["description"]="Observe a unit casting or channeling on supported readable clients. A readable inactive result returns active=false. Active records contain name and independently available remainingSeconds and interruptible fields, with remainingReason or interruptibleReason when an optional field is unavailable. Missing, failed or restricted observations return nil with a reason.",["kind"]="function",["line"]=27,["parameters"]={"self","unit","kind"},["returns"]={{["description"]="Fresh readable record with active, optional name, remainingSeconds and interruptible. Remaining time is in seconds and is clamped to zero. An unavailable optional field has its own reason; it does not invalidate a readable active name.",["type"]="table | nil"},{["description"]="Availability or query-validation reason when the whole observation is unavailable.",["type"]="string | nil"}}},["finite"]={["bindings"]={},["code"]="\010    return type(value)=='number' and value==value and value<math.huge and value>-math.huge\010",["kind"]="function",["line"]=4,["parameters"]={"value"}},["interruptibility"]={["bindings"]={["platform"]="builtin:Platform/casting.lua:platform"},["code"]="\010    if not platform:CanReadValue(flag) then return nil,'restricted-value' end\010    if flag==nil then return nil,'interruptibility-unavailable' end\010    if type(flag)~='boolean' then return nil,'invalid-api-result' end\010    return not flag\010",["kind"]="function",["line"]=18,["parameters"]={"flag"}},["platform"]={["kind"]="value"},["remainingSeconds"]={["bindings"]={["finite"]="builtin:Platform/casting.lua:finite",["platform"]="builtin:Platform/casting.lua:platform"},["code"]="\010    if not platform:CanReadValue(ending) then return nil,'restricted-value' end\010    if ending==nil then return nil,'cast-time-unavailable' end\010    if not finite(ending) or ending<0 then return nil,'invalid-api-result' end\010    if type(GetTime)~='function' then return nil,'missing-api' end\010    local ok,now=pcall(GetTime)\010    if not ok then return nil,'api-error' end\010    if not platform:CanReadValue(now) then return nil,'restricted-value' end\010    if not finite(now) or now<0 then return nil,'invalid-api-result' end\010    return math.max(0,ending/1000-now)\010",["kind"]="function",["line"]=7,["parameters"]={"ending"}}},["hash"]="68742a0d8497fda64dff7e6e5199ced7a1b95ec36d41bf3ce8eb8cce8acf9268"},["Platform/form.lua"]={["bindings"]={["Platform_GetPlayerFormObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"}},["bindings"]={},["callName"]="addon.Platform:GetPlayerFormObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if type(GetShapeshiftForm)~='function' then return nil,'missing-api' end\010    local ok,result=pcall(GetShapeshiftForm)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(result) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(result) then return nil,'restricted-value' end\010    if result==nil then return nil,'form-unavailable' end\010    if type(result)~='number' or result~=result or result==math.huge or result==-math.huge then return nil,'invalid-api-result' end\010    return result\010",["description"]="Observe the current player form with one protected zero-argument GetShapeshiftForm call. Preserve every readable finite numeric result, including zero, signed and fractional values; no stronger native index domain is inferred. Missing, failed, nil, restricted or nonfinite data remains unavailable. No form count, class, spell ID, unit or optional argument is added.",["kind"]="function",["line"]=6,["parameters"]={"self"},["returns"]={{["description"]="Readable finite current-form observation, including zero for the current unshifted comparison; nil when unavailable.",["type"]="number | nil"},{["description"]="Client-policy, capability, call or observation availability reason for a nil form.",["type"]="string | nil"}}}},["hash"]="fc3a6bd423b769cec1ffe604c067a9187e36af323a3494c154d044f5e4f29a3c"},["Platform/glyphs.lua"]={["bindings"]={["Platform_GetGlyphItemInfo"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Positive integer glyph item ID stored by the condition; arrays, item-set keys and spell IDs are not item references.",["name"]="itemID",["type"]="number"},{["description"]="Optional positive class ID; nil queries the current player class under protection.",["name"]="classID",["type"]="number | nil"}},["bindings"]={["integer"]="builtin:Platform/glyphs.lua:integer"},["callName"]="addon.Platform:GetGlyphItemInfo",["code"]="\010    if not self:CanReadValue(itemID) or not self:CanReadValue(classID) then return nil,'restricted-value' end\010    if not integer(itemID,1) then return nil,'invalid-item' end\010    if classID==nil then\010        if type(UnitClass)~='function' then return nil,'missing-api' end\010        local ok,tuple=pcall(function() return {UnitClass('player')} end)\010        if not ok then return nil,'api-error' end\010        classID=tuple[3]\010        if not self:CanReadValue(classID) then return nil,'restricted-value' end\010        if classID==nil then return nil,'class-data-unavailable' end\010    end\010    if not integer(classID,1) then return nil,'invalid-class' end\010    local record,reason=self:GetItemInfoInstant(itemID)\010    if not record then return nil,reason end\010    if record.classID~=16 or record.subClassID~=classID then return nil,'invalid-glyph-item' end\010    return record\010",["description"]="Classify a numeric item as a glyph for the requested class, using guarded native item metadata. Class is optional and defaults to the readable player class. This establishes item classification only, not equipped status or an item-to-glyph-spell ID mapping.",["kind"]="function",["line"]=6,["parameters"]={"self","itemID","classID"},["returns"]={{["description"]="Readable canonical itemID/classID/subClassID record when the item is a glyph for the requested class; nil for invalid or unavailable metadata.",["type"]="table | nil"},{["description"]="Classification, validation or availability reason for a nil result.",["type"]="string | nil"}}},["Platform_GetGlyphSocketSnapshot"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"}},["bindings"]={["integer"]="builtin:Platform/glyphs.lua:integer",["layout"]="builtin:Platform/glyphs.lua:layout",["socket"]="builtin:Platform/glyphs.lua:socket"},["callName"]="addon.Platform:GetGlyphSocketSnapshot",["code"]="\010    local position=layout(self:GetClientInfo())\010    if not position then return nil,'unsupported-glyph-layout' end\010    if type(GetNumGlyphSockets)~='function' then return nil,'missing-api' end\010    local ok,count=pcall(GetNumGlyphSockets)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(count) then return nil,'restricted-value' end\010    if count==nil then return nil,'glyph-data-unavailable' end\010    if not integer(count,0) or count>64 then return nil,'invalid-api-result' end\010    local fn=GetGlyphSocketInfo\010    if count>0 and type(fn)~='function' then return nil,'missing-api' end\010    local result={slots={},complete=true}\010    for index=1,count do\010        local record=socket(self,fn,index,position)\010        result.slots[index]=record\010        if record.active==nil then result.complete=false end\010    end\010    return result\010",["description"]="Observe glyph sockets on verified Wrath, Cata and Mists client layouts. Returns slots and a complete flag. Each slot has active=false when known locked or empty, active=true plus spellID when occupied, or nil active plus reason when unavailable. Unknown layouts and failed count queries return nil with a reason. This does not compare item names or prove exact item-to-spell identity.",["kind"]="function",["line"]=52,["parameters"]={"self"},["returns"]={{["description"]="Normalized bounded socket snapshot with slots and complete, or nil when the query is unavailable.",["type"]="table | nil"},{["description"]="Policy, validation or availability reason for a nil snapshot.",["type"]="string | nil"}}},["integer"]={["bindings"]={},["code"]="\010    return type(value)=='number' and value==value and value>=minimum and value<math.huge and value%1==0\010",["kind"]="function",["line"]=3,["parameters"]={"value","minimum"}},["layout"]={["bindings"]={},["code"]="\010    local editions={\010        [11]={expansion=2,prefix='3.4.',last=3,base=30400,position=3},\010        [14]={expansion=3,prefix='4.4.',last=2,base=40400,position=4},\010        [19]={expansion=4,prefix='5.5.',last=4,base=50500,position=4},\010    }\010    local edition=editions[info.projectId]\010    if not edition or info.family~='progression' or info.expansion~=edition.expansion then return nil end\010    for patch=0,edition.last do\010        if info.version==edition.prefix..patch and info.interface==edition.base+patch then return edition.position end\010    end\010",["kind"]="function",["line"]=27,["parameters"]={"info"}},["socket"]={["bindings"]={["integer"]="builtin:Platform/glyphs.lua:integer"},["code"]="\010    local ok,tuple=pcall(function() return {fn(index)} end)\010    if not ok then return {slot=index,reason='api-error'} end\010    local enabled,kind,spell=tuple[1],tuple[2],tuple[position]\010    if not self:CanReadValue(enabled) or not self:CanReadValue(kind) then return {slot=index,reason='restricted-value'} end\010    if enabled==nil and kind==nil then return {slot=index,reason='glyph-socket-unavailable'} end\010    if not integer(kind,1) or enabled~=nil and type(enabled)~='boolean' then return {slot=index,reason='invalid-api-result'} end\010    if not enabled then return {slot=index,active=false} end\010    if not self:CanReadValue(spell) then return {slot=index,reason='restricted-value'} end\010    if spell==nil then return {slot=index,active=false} end\010    if not integer(spell,1) then return {slot=index,reason='invalid-api-result'} end\010    return {slot=index,active=true,spellID=spell}\010",["kind"]="function",["line"]=39,["parameters"]={"self","fn","index","position"}}},["hash"]="b842e38f8fe186592339cf81b8c45bb434a39798000c0a27f6f48de7f1180986"},["Platform/groups.lua"]={["bindings"]={["Platform_GetGroupMembership"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="True requests raid membership; false or nil requests any group membership.",["name"]="raidOnly",["type"]="boolean | nil"}},["bindings"]={},["callName"]="addon.Platform:GetGroupMembership",["code"]="\010    if not self:CanReadValue(raidOnly) then return nil,'restricted-value' end\010    if raidOnly~=nil and type(raidOnly)~='boolean' then return nil,'invalid-group-query' end\010    if self:GetClientInfo().family=='unknown' then return nil,'unsupported-client' end\010    local fn\010    if raidOnly then fn=IsInRaid else fn=IsInGroup end\010    if type(fn)~='function' then return nil,'missing-api' end\010    local ok,member=pcall(fn)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(member) then return nil,'restricted-value' end\010    if member==nil then return nil,'group-data-unavailable' end\010    if type(member)~='boolean' then return nil,'invalid-api-result' end\010    return member\010",["description"]="Read public group membership on identified client families. Unknown clients are unsupported. True raidOnly checks IsInRaid; false or nil checks IsInGroup using its native default group category. A readable false result stays false. Missing, failed, malformed or restricted observations return nil with a reason.",["kind"]="function",["line"]=6,["parameters"]={"self","raidOnly"},["returns"]={{["description"]="Observed membership, or nil when unavailable.",["type"]="boolean | nil"},{["description"]="Validation or availability reason for a nil result.",["type"]="string | nil"}}}},["hash"]="c9a001ecc3f69a0b3769d5772e6490c4ead926b84c6feb3ffd2eca5065b20115"},["Platform/health_forecast.lua"]={["bindings"]={["Platform_GetHealthForecastIdentityObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Selected nonempty unit token.",["name"]="unit",["type"]="string"}},["bindings"]={},["callName"]="addon.Platform:GetHealthForecastIdentityObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local ok,exists=pcall(UnitExists,unit)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return false end\010    if type(UnitGUID)~='function' then return nil,'missing-api' end\010    local success,guid=pcall(UnitGUID,unit)\010    if not success then return nil,'api-error' end\010    if not self:CanReadValue(guid) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(guid) then return nil,'restricted-value' end\010    if guid==nil then return nil,'unit-guid-unavailable' end\010    if type(guid)~='string' or guid=='' then return nil,'invalid-api-result' end\010    return guid\010",["description"]="On probe-policy clients observe exact UnitExists(unit), then UnitGUID(unit) only for a present unit. Known absence is false. Present identity requires a readable nonempty GUID; missing, failed, malformed or restricted required facts are unavailable. No health, provider or extra-unit observation is added.",["kind"]="function",["line"]=25,["parameters"]={"self","unit"},["returns"]={{["description"]="Present GUID, false for known absence, or nil when unavailable.",["type"]="string | boolean | nil"},{["description"]="Policy, validation or observation availability reason.",["type"]="string | nil"}}},["Platform_GetHealthForecastProviderObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Selected unit token forwarded as the only provider argument.",["name"]="unit",["type"]="string"}},["bindings"]={["providerValue"]="builtin:Platform/health_forecast.lua:providerValue",["readField"]="builtin:Platform/health_forecast.lua:readField"},["callName"]="addon.Platform:GetHealthForecastProviderObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    local provider=_G.RealMobHealth\010    if not self:CanReadValue(provider) then return nil,'restricted-value' end\010    if provider==nil or provider==false then return {} end\010    local api,why=readField(self,provider,'GetUnitHealth')\010    if why then return nil,why end\010    if type(api)~='function' then return nil,'missing-api' end\010    local ok,current,maximum=pcall(api,unit)\010    if not ok then return nil,'api-error' end\010    local value,reason=providerValue(self,current)\010    if reason then return nil,reason end\010    local max,maxReason=providerValue(self,maximum)\010    if maxReason then return nil,maxReason end\010    return {current=value,maximum=max}\010",["description"]="Read optional RealMobHealth using its exact one-argument dot call. Absent nil/false namespace returns an empty record. Normalize current and maximum independently: nil/false fields permit native fallback, numeric zero remains present. Malformed, failed, restricted, negative or nonfinite consumed provider facts are unavailable. No provider or stale fallback cache is used.",["kind"]="function",["line"]=64,["parameters"]={"self","unit"},["returns"]={{["description"]="Partial current/maximum record, empty when provider absent, or nil when unavailable.",["type"]="table | nil"},{["description"]="Provider, validation or observation availability reason.",["type"]="string | nil"}}},["Platform_GetHealthForecastTimeObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"}},["bindings"]={["finite"]="builtin:Platform/health_forecast.lua:finite"},["callName"]="addon.Platform:GetHealthForecastTimeObservation",["code"]="\010    if type(GetTime)~='function' then return nil,'missing-api' end\010    local ok,now=pcall(GetTime)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(now) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(now) then return nil,'restricted-value' end\010    if not finite(now) then return nil,'invalid-forecast-time' end\010    return now\010",["description"]="Observe a fresh protected zero-argument GetTime for a needed health forecast. Require readability and a finite number; preserve signed and fractional values without adding a monotonic, integral or nonnegative restriction. No clock cache or extra native query is used.",["kind"]="function",["line"]=83,["parameters"]={"self"},["returns"]={{["description"]="Fresh readable finite clock, or nil when unavailable.",["type"]="number | nil"},{["description"]="Capability or clock observation availability reason.",["type"]="string | nil"}}},["Platform_GetHealthForecastValueObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Selected nonempty unit token; this call alone does not establish presence.",["name"]="unit",["type"]="string"},{["description"]="Closed scalar kind: current or maximum.",["name"]="kind",["type"]="string"}},["bindings"]={["finite"]="builtin:Platform/health_forecast.lua:finite"},["callName"]="addon.Platform:GetHealthForecastValueObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) or not self:CanReadValue(kind) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    local api\010    if kind=='current' then api=UnitHealth\010    elseif kind=='maximum' then api=UnitHealthMax\010    else return nil,'invalid-health-forecast-query' end\010    if type(api)~='function' then return nil,'missing-api' end\010    local ok,value=pcall(api,unit)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(value) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(value) then return nil,'restricted-value' end\010    if value==nil then return nil,'health-data-unavailable' end\010    if not finite(value) or value<0 then return nil,'invalid-api-result' end\010    return value\010",["description"]="Read a lazy health scalar after a separate identity gate. Kind current uses exact UnitHealth(unit); maximum uses exact UnitHealthMax(unit). Probe-policy clients accept readable finite nonnegative numbers including zero. No repeated existence/GUID call or alternate tuple fallback is added.",["kind"]="function",["line"]=46,["parameters"]={"self","unit","kind"},["returns"]={{["description"]="Finite nonnegative native health scalar, or nil when unavailable.",["type"]="number | nil"},{["description"]="Policy, validation or required observation availability reason.",["type"]="string | nil"}}},["finite"]={["bindings"]={},["code"]="\010    return type(value)=='number' and value==value and value<math.huge and value>-math.huge\010",["kind"]="function",["line"]=4,["parameters"]={"value"}},["providerValue"]={["bindings"]={["finite"]="builtin:Platform/health_forecast.lua:finite"},["code"]="\010    if not self:CanReadValue(value) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(value) then return nil,'restricted-value' end\010    if value==nil or value==false then return nil end\010    if not finite(value) or value<0 then return nil,'invalid-api-result' end\010    return value\010",["kind"]="function",["line"]=17,["parameters"]={"self","value"}},["readField"]={["bindings"]={},["code"]="\010    if not self:CanReadValue(object) then return nil,'restricted-value' end\010    if type(object)~='table' then return nil,'invalid-api-result' end\010    local ok,value=pcall(function() return object[key] end)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(value) then return nil,'restricted-value' end\010    return value\010",["kind"]="function",["line"]=8,["parameters"]={"self","object","key"}}},["hash"]="9eae4564c6c5ca6cadd84d90bb44a647b09f2b9aa271fd3c863e92b4b63549e0"},["Platform/instance.lua"]={["bindings"]={["Platform_GetInstanceObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"}},["bindings"]={},["callName"]="addon.Platform:GetInstanceObservation",["code"]="\010    local family=self:GetClientInfo().family\010    if family~='retail' and family~='forever' and family~='era' and family~='tbc' and family~='progression' then return nil,'unsupported-policy' end\010    if type(IsInInstance)~='function' then return nil,'missing-api' end\010    local ok,inInstance,instanceType=pcall(IsInInstance)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(inInstance) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(inInstance) then return nil,'restricted-value' end\010    if inInstance==nil then return nil,'instance-data-unavailable' end\010    if type(inInstance)~='boolean' then return nil,'invalid-api-result' end\010    if not inInstance then return {inInstance=false} end\010    if not self:CanReadValue(instanceType) then return {inInstance=true,instanceTypeReason='restricted-value'} end\010    if canaccessvalue and not canaccessvalue(instanceType) then return {inInstance=true,instanceTypeReason='restricted-value'} end\010    if instanceType==nil then return {inInstance=true,instanceTypeReason='instance-type-unavailable'} end\010    if type(instanceType)~='string' then return {inInstance=true,instanceTypeReason='invalid-api-result'} end\010    return {inInstance=true,instanceType=instanceType}\010",["description"]="Observe one protected zero-argument IsInInstance tuple. Required readable Boolean membership is independent of the type field: known outside returns without interpreting the unused type; inside returns a readable string type or an instanceTypeReason when that secondary field is unavailable. Callers testing outside need only membership; inside type comparisons must check the secondary reason. No outdoors, zone or unit inference is added.",["kind"]="function",["line"]=5,["parameters"]={"self"},["returns"]={{["description"]="Record with inInstance and, when inside, instanceType or instanceTypeReason; nil when membership is unavailable.",["type"]="table | nil"},{["description"]="Client-policy, native-call or required membership availability reason for a nil record.",["type"]="string | nil"}}}},["hash"]="6b95a219c27f8dee7e3c39b082cf5b8dad66a8f86adb980acff4c7ba3ad727e0"},["Platform/items.lua"]={["bindings"]={["Platform_GetItemInfoInstant"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Positive item ID or native-recognized item name/link to classify.",["name"]="item",["type"]="number | string"}},["bindings"]={["finite"]="builtin:Platform/items.lua:finite",["identifier"]="builtin:Platform/items.lua:identifier"},["callName"]="addon.Platform:GetItemInfoInstant",["code"]="\010    local valid,reason=identifier(item)\010    if not valid then return nil,reason end\010    local fn=C_Item and C_Item.GetItemInfoInstant\010    if type(fn)~='function' then fn=GetItemInfoInstant end\010    if type(fn)~='function' then return nil,'missing-api' end\010    local ok,tuple=pcall(function() return {fn(item)} end)\010    if not ok then return nil,'api-error' end\010    local id,class,subclass=tuple[1],tuple[6],tuple[7]\010    if not self:CanReadValue(id) or not self:CanReadValue(class) or not self:CanReadValue(subclass) then return nil,'restricted-value' end\010    if id==nil then return nil,'item-data-unavailable' end\010    if not finite(id) or id<=0 or id%1~=0 or not finite(class) or class%1~=0\010        or not finite(subclass) or subclass%1~=0 or type(item)=='number' and id~=item then return nil,'invalid-api-result' end\010    return {itemID=id,classID=class,subClassID=subclass}\010",["description"]="Read normalized native item classification metadata. The record contains canonical itemID, classID and subClassID; it does not require loaded item display text. Missing, failed, malformed or restricted metadata returns nil with a reason.",["kind"]="function",["line"]=44,["parameters"]={"self","item"},["returns"]={{["description"]="Readable canonical item classification record, or nil when unavailable.",["type"]="table | nil"},{["description"]="Validation or availability reason for a nil result.",["type"]="string | nil"}}},["finite"]={["bindings"]={},["code"]="\010    return type(value)==\"number\" and value==value and value>=0 and value<math.huge\010",["kind"]="function",["line"]=40,["parameters"]={"value"}},["identifier"]={["bindings"]={["platform"]="builtin:Platform/items.lua:platform"},["code"]="\010    if not platform:CanReadValue(item) then return nil,\"restricted-value\" end\010    if type(item)==\"number\" and item>0 and item<math.huge and item%1==0 then return true end\010    if type(item)==\"string\" and #item>0 and #item<=1024 then return true end\010    return nil,\"invalid-item\"\010",["kind"]="function",["line"]=3,["parameters"]={"item"}},["platform"]={["kind"]="value"}},["hash"]="fc3e3de14f06bdb589de9c99347fbd9e676c57ebcd95ae0fd6e4a7c641a4e40a"},["Platform/loss_of_control.lua"]={["bindings"]={["Platform_GetLossOfControlCount"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"}},["bindings"]={},["callName"]="addon.Platform:GetLossOfControlCount",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    local namespace=C_LossOfControl\010    if not self:CanReadValue(namespace) then return nil,'restricted-value' end\010    if type(namespace)~='table' then return nil,'missing-api' end\010    local methodOk,method=pcall(function() return namespace.GetActiveLossOfControlDataCount end)\010    if not methodOk then return nil,'api-error' end\010    if not self:CanReadValue(method) then return nil,'restricted-value' end\010    if type(method)~='function' then return nil,'missing-api' end\010    local ok,count=pcall(method)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(count) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(count) then return nil,'restricted-value' end\010    if count==nil then return nil,'loss-of-control-count-unavailable' end\010    if type(count)~='number' or count~=count or count==math.huge or count==-math.huge or count<0 or count%1~=0 then return nil,'invalid-api-result' end\010    if count>256 then return nil,'loss-of-control-budget-exceeded' end\010    return count\010",["description"]="Read the documented active loss-of-control count with a protected zero-argument dot call. Require a readable finite nonnegative integer. Zero is a complete empty scan and does not require a row API. RM limits a scan to 256 rows and returns unavailable beyond that resource budget; this is not a declared native maximum. Required missing, failed, restricted or malformed observations remain unavailable.",["kind"]="function",["line"]=5,["parameters"]={"self"},["returns"]={{["description"]="Known active count from zero through the RM scan budget, or nil when unavailable.",["type"]="number | nil"},{["description"]="Combat-policy, capability, observation or scan-budget reason for a nil count.",["type"]="string | nil"}}},["Platform_GetLossOfControlEvent"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Native one-based integral active-row index within the 256-row RM scan budget.",["name"]="index",["type"]="number"},{["description"]="Exactly type or school; selects the required subject field without requiring the other.",["name"]="kind",["type"]="string"}},["bindings"]={},["callName"]="addon.Platform:GetLossOfControlEvent",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(index) or not self:CanReadValue(kind) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(index) then return nil,'restricted-value' end\010    if type(index)~='number' or index~=index or index==math.huge or index==-math.huge or index<1 or index%1~=0 then return nil,'invalid-loss-of-control-query' end\010    if kind~='type' and kind~='school' then return nil,'invalid-loss-of-control-query' end\010    if index>256 then return nil,'loss-of-control-budget-exceeded' end\010    local namespace=C_LossOfControl\010    if not self:CanReadValue(namespace) then return nil,'restricted-value' end\010    if type(namespace)~='table' then return nil,'missing-api' end\010    local methodOk,method=pcall(function() return namespace.GetActiveLossOfControlData end)\010    if not methodOk then return nil,'api-error' end\010    if not self:CanReadValue(method) then return nil,'restricted-value' end\010    if type(method)~='function' then return nil,'missing-api' end\010    local ok,event=pcall(method,index)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(event) then return nil,'restricted-value' end\010    if event==nil then return nil,'loss-of-control-event-unavailable' end\010    if type(event)~='table' then return nil,'invalid-api-result' end\010    local subjectOk,subject=pcall(function() return event[kind=='type' and 'locType' or 'lockoutSchool'] end)\010    if not subjectOk then return nil,'api-error' end\010    if not self:CanReadValue(subject) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(subject) then return nil,'restricted-value' end\010    if subject==nil then return nil,'loss-of-control-subject-unavailable' end\010    local record={}\010    if kind=='type' then\010        if type(subject)~='string' then return nil,'invalid-api-result' end\010        record.locType=subject\010    else\010        if type(subject)~='number' or subject~=subject or subject==math.huge or subject==-math.huge or subject<0 or subject%1~=0 then return nil,'invalid-api-result' end\010        record.lockoutSchool=subject\010    end\010    local timeOk,remaining=pcall(function() return event.timeRemaining end)\010    if not timeOk then record.timeRemainingReason='api-error'\010    elseif not self:CanReadValue(remaining) then record.timeRemainingReason='restricted-value'\010    elseif canaccessvalue and not canaccessvalue(remaining) then record.timeRemainingReason='restricted-value'\010    elseif remaining==nil then record.timeRemainingReason='loss-of-control-time-unavailable'\010    elseif type(remaining)~='number' or remaining~=remaining or remaining==math.huge or remaining==-math.huge then record.timeRemainingReason='invalid-api-result'\010    else record.timeRemaining=remaining end\010    return record\010",["description"]="Read one documented active loss-of-control row by its native index and requested subject kind. Type queries require only the readable control type string; school queries require only the readable finite nonnegative integer school mask. Optional timing is returned as a finite timeRemaining or an explicit per-field reason, so an unrelated subject does not require a usable timer. Missing rows are unavailable snapshot observations. No display fields, inferred deadline, duration sum, maximum or native alias fallback is used.",["kind"]="function",["line"]=26,["parameters"]={"self","index","kind"},["returns"]={{["description"]="Normalized requested subject with finite timeRemaining or timeRemainingReason; nil when the required row or subject is unavailable.",["type"]="table | nil"},{["description"]="Policy, query, capability or required row/subject availability reason for a nil record.",["type"]="string | nil"}}}},["hash"]="bc225755be761e03164504c411b2fcc000ef2c9838620d31af8fff6cfb9886ee"},["Platform/pet.lua"]={["bindings"]={["Platform_GetPetObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="True requests the formatted pet name; false or omitted reads presence only.",["name"]="includeName",["type"]="boolean | nil"}},["bindings"]={},["callName"]="addon.Platform:GetPetObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(includeName) then return nil,'restricted-value' end\010    if includeName~=nil and type(includeName)~='boolean' then return nil,'invalid-pet-query' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local ok,exists=pcall(UnitExists,'pet')\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'pet-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    local record={exists=exists}\010    if not exists or not includeName then return record end\010    if type(GetUnitName)~='function' then return nil,'missing-api' end\010    local nameOk,name=pcall(GetUnitName,'pet')\010    if not nameOk then return nil,'api-error' end\010    if not self:CanReadValue(name) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(name) then return nil,'restricted-value' end\010    if name==nil then return nil,'pet-name-unavailable' end\010    if type(name)~='string' or name=='' then return nil,'invalid-api-result' end\010    record.name=name\010    return record\010",["description"]="Observe exact pet existence and optionally its formatted GetUnitName display name. Presence-only queries never require name data. Known absence skips the name query. Present pets require a readable nonempty name only when requested; required missing, failed, nil, restricted or malformed observations return nil with a reason. The display helper is called with its single original pet argument, without UnitName fallback or inferred bar, health or ability state.",["kind"]="function",["line"]=6,["parameters"]={"self","includeName"},["returns"]={{["description"]="Pet observation with Boolean exists and, for a requested present pet, name; nil when required data is unavailable.",["type"]="table | nil"},{["description"]="Policy, query-validation or availability reason for a nil pet observation.",["type"]="string | nil"}}}},["hash"]="8fde59206c561e9326987a2bea493a43533f2b011d9ea7e9d84bd3f4b3dd2967"},["Platform/player_flags.lua"]={["bindings"]={["Platform_GetPlayerFlagObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="One of stealthed, control or outdoors; no other predicate is invoked.",["name"]="kind",["type"]="string"}},["bindings"]={},["callName"]="addon.Platform:GetPlayerFlagObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(kind) then return nil,'restricted-value' end\010    if kind~='stealthed' and kind~='control' and kind~='outdoors' then return nil,'invalid-player-flag-query' end\010    local api\010    if kind=='stealthed' then api=IsStealthed\010    elseif kind=='control' then api=HasFullControl\010    else api=IsOutdoors end\010    if type(api)~='function' then return nil,'missing-api' end\010    local ok,result=pcall(api)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(result) then return nil,'restricted-value' end\010    if result==nil then return nil,'player-flag-unavailable' end\010    if type(result)~='boolean' then return nil,'invalid-api-result' end\010    return result\010",["description"]="Observe one independent zero-argument player flag: stealthed uses IsStealthed, control uses HasFullControl, and outdoors uses IsOutdoors. Readable true and false retain their meanings. Required missing, failed, nil, restricted or malformed data returns nil with a reason. No existence, instance or ability-usability inference is added.",["kind"]="function",["line"]=6,["parameters"]={"self","kind"},["returns"]={{["description"]="Readable selected flag or nil when required data is unavailable.",["type"]="boolean | nil"},{["description"]="Policy, query-validation or availability reason for a nil player flag.",["type"]="string | nil"}}}},["hash"]="9ba14b70151602314d14aea735dad59286236bb9a9eb2e0bbde3e0415964d760"},["Platform/player_movement.lua"]={["bindings"]={["Platform_GetPlayerMovementObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"}},["bindings"]={},["callName"]="addon.Platform:GetPlayerMovementObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if type(GetUnitSpeed)~='function' then return nil,'missing-api' end\010    local ok,speed=pcall(GetUnitSpeed,'player')\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(speed) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(speed) then return nil,'restricted-value' end\010    if speed==nil then return nil,'movement-data-unavailable' end\010    if type(speed)~='number' or speed~=speed or speed==math.huge or speed==-math.huge or speed<0 then return nil,'invalid-api-result' end\010    return {speed=speed}\010",["description"]="Observe the player current movement speed on supported readable clients. This queries GetUnitSpeed for player only, without testing another unit or redirecting vehicle ownership. Zero means stationary; positive finite fractional speeds remain valid. Missing, failed, restricted or malformed observations return nil with a reason.",["kind"]="function",["line"]=4,["parameters"]={"self"},["returns"]={{["description"]="Fresh readable record with finite nonnegative speed, or nil when unavailable.",["type"]="table | nil"},{["description"]="Policy or availability reason for a nil movement observation.",["type"]="string | nil"}}}},["hash"]="a5cf9f162f8f8468eaf647686cafd3abe3eafd9d4dad2f147d5fa2db29f12a88"},["Platform/points.lua"]={["bindings"]={["Platform_GetUnitPointIdentityObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Exact unit token passed unchanged to UnitExists and, when required, UnitClass.",["name"]="unit",["type"]="string"},{["description"]="True also requires the present unit class filename; false reads existence only.",["name"]="includeClass",["type"]="boolean"}},["bindings"]={},["callName"]="addon.Platform:GetUnitPointIdentityObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) or not self:CanReadValue(includeClass) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if type(includeClass)~='boolean' then return nil,'invalid-point-identity-query' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local existsOK,exists=pcall(UnitExists,unit)\010    if not existsOK then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return {exists=false} end\010    if not includeClass then return {exists=true} end\010    if type(UnitClass)~='function' then return nil,'missing-api' end\010    local ok,_,class=pcall(UnitClass,unit)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(class) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(class) then return nil,'restricted-value' end\010    if class==nil then return nil,'point-class-unavailable' end\010    if type(class)~='string' or class=='' then return nil,'invalid-api-result' end\010    return {exists=true,class=class}\010",["description"]="Observe exact selected-unit existence and optionally its class filename for point-resource conditions. Known absence returns exists=false without reading class. Present units require only UnitClass return two when requested; unused localized names and IDs do not affect availability. Required missing, failed, restricted or malformed observations remain unavailable. This does not select a resource or cache identity.",["kind"]="function",["line"]=6,["parameters"]={"self","unit","includeClass"},["returns"]={{["description"]="Readable record with Boolean exists and the requested class filename when present; nil when required data is unavailable.",["type"]="table | nil"},{["description"]="Policy, query-validation or required observation availability reason for a nil record.",["type"]="string | nil"}}},["Platform_GetUnitPointPowerObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Exact unit token whose selected resource quantity is requested.",["name"]="unit",["type"]="string"},{["description"]="Explicit readable finite nonnegative integer power selector, including zero.",["name"]="powerType",["type"]="number"},{["description"]="Exactly current for UnitPower or maximum for UnitPowerMax; no other native query is added.",["name"]="kind",["type"]="string"}},["bindings"]={},["callName"]="addon.Platform:GetUnitPointPowerObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) or not self:CanReadValue(powerType) or not self:CanReadValue(kind) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if type(powerType)~='number' or powerType~=powerType or powerType<0 or powerType==math.huge or powerType%1~=0 then return nil,'invalid-point-power-query' end\010    if kind~='current' and kind~='maximum' then return nil,'invalid-point-power-query' end\010    local api\010    if kind=='current' then api=UnitPower else api=UnitPowerMax end\010    if type(api)~='function' then return nil,'missing-api' end\010    local ok,result=pcall(api,unit,powerType)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(result) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(result) then return nil,'restricted-value' end\010    if result==nil then return nil,'point-power-unavailable' end\010    if type(result)~='number' or result~=result or result==math.huge or result==-math.huge then return nil,'invalid-api-result' end\010    return result\010",["description"]="Read one explicitly selected point-resource quantity with an exact two-argument UnitPower or UnitPowerMax query. The selector is required; no primary-resource inference or actor remapping occurs. Preserve finite signed, fractional and zero quantities without clamping. Missing, failed, restricted or nonfinite data remains unavailable. Current and maximum are separate observations so callers can share current snapshots while requesting maximum lazily.",["kind"]="function",["line"]=30,["parameters"]={"self","unit","powerType","kind"},["returns"]={{["description"]="Finite native resource quantity, retaining its sign and fractional part; nil when unavailable.",["type"]="number | nil"},{["description"]="Policy, query-validation or availability reason for a nil quantity.",["type"]="string | nil"}}}},["hash"]="cc118c323de118cf921263a043e42092c9ebe79671d22e1a4727905212c3df07"},["Platform/range.lua"]={["bindings"]={["Platform_GetNameplateMaxDistance"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"}},["bindings"]={},["callName"]="addon.Platform:GetNameplateMaxDistance",["code"]="\010    local query=C_CVar and C_CVar.GetCVar or GetCVar\010    if type(query)~='function' then return nil,'missing-api' end\010    local ok,value=pcall(query,'nameplateMaxDistance')\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(value) then return nil,'restricted-value' end\010    if type(value)~='string' and type(value)~='number' then return nil,'nameplate-distance-unavailable' end\010    local maximum=tonumber(value)\010    if not maximum or maximum~=maximum or maximum<=0 or maximum==math.huge then return nil,'nameplate-distance-unavailable' end\010    return maximum\010",["description"]="Read the current positive nameplate visibility distance using the supported CVar API. This limits a Distance Count query; it does not prove that all nearby units have been observed. Missing, malformed, restricted or failed observations return nil with a reason.",["kind"]="function",["line"]=42,["parameters"]={"self"},["returns"]={{["description"]="Current positive visibility distance in yards; nil when unavailable.",["type"]="number | nil"},{["description"]="Availability reason for a nil result.",["type"]="string | nil"}}},["Platform_GetRangeCheckBounds"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Current unit token whose distance from the player should be observed.",["name"]="unit",["type"]="string"}},["bindings"]={},["callName"]="addon.Platform:GetRangeCheckBounds",["code"]="\010    if not self:CanReadValue(unit) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if not LibStub then return nil,'missing-range-provider' end\010    local loaded,provider=pcall(function() return LibStub('LibRangeCheck-3.0',true) end)\010    if not loaded or not provider or type(provider.GetRange)~='function' then return nil,'missing-range-provider' end\010    local ok,minimum,maximum=pcall(provider.GetRange,provider,unit)\010    if not ok then return nil,'range-provider-error' end\010    if not self:CanReadValue(minimum) or not self:CanReadValue(maximum) then return nil,'restricted-value' end\010    for _,bound in pairs({minimum=minimum,maximum=maximum}) do\010        if type(bound)~='number' or bound~=bound or bound<0 or bound==math.huge then return nil,'invalid-range-result' end\010    end\010    if minimum==nil and maximum==nil then return nil,'range-unavailable' end\010    if minimum and maximum and minimum>maximum then return nil,'invalid-range-result' end\010    return {minimum=minimum,maximum=maximum}\010",["description"]="Read the public LibRangeCheck interval for a unit. A successful upper bound is inclusive; a positive failed lower bound is strict. A zero lower floor is synthetic. Neither bound is an exact distance, and a missing upper bound is not proof that the unit is outside every radius. Unavailable, malformed, restricted or failed observations return nil with a reason.",["kind"]="function",["line"]=56,["parameters"]={"self","unit"},["returns"]={{["description"]="Readable interval with optional minimum and maximum bounds in yards. At least one bound is present; nil when unavailable.",["type"]="table | nil"},{["description"]="Availability or validation reason for a nil result.",["type"]="string | nil"}}}},["hash"]="694ad01a2e8aaa0a140b1cc1f78715033605cf7f5f6e105c8b72f9439737c55e"},["Platform/roster_class.lua"]={["bindings"]={["Platform_GetRosterClassObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Exact helper-owned player, party1..party4 or raid1..raid40 token.",["name"]="unit",["type"]="string"}},["bindings"]={["rosterUnit"]="builtin:Platform/roster_class.lua:rosterUnit"},["callName"]="addon.Platform:GetRosterClassObservation",["code"]="\010    if not self:CanReadValue(unit) then return nil,'restricted-value' end\010    if type(unit)~='string' or not rosterUnit(unit) then return nil,'invalid-roster-unit' end\010    if self:GetClientInfo().family=='unknown' then return nil,'unsupported-client' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local ok,exists=pcall(UnitExists,unit)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'roster-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return false end\010    if type(UnitClass)~='function' then return nil,'missing-api' end\010    local success,_,class=pcall(UnitClass,unit)\010    if not success then return nil,'api-error' end\010    if not self:CanReadValue(class) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(class) then return nil,'restricted-value' end\010    if class==nil then return nil,'roster-class-unavailable' end\010    if type(class)~='string' or class=='' then return nil,'invalid-api-result' end\010    return class\010",["description"]="Read public roster identity on identified client families. Input routing is limited to player, party1 through party4 and raid1 through raid40. Call UnitExists with that exact one-argument token first; known false returns false without querying class. For a present unit, consume only UnitClass return two as a readable nonempty class filename string, without a class enum restriction. Missing, failed, malformed or restricted required facts return nil with a reason.",["kind"]="function",["line"]=10,["parameters"]={"self","unit"},["returns"]={{["description"]="Observed class filename string, false for a known absent unit, or nil when unavailable.",["type"]="string | boolean | nil"},{["description"]="Validation, policy or availability reason for a nil result.",["type"]="string | nil"}}},["rosterUnit"]={["bindings"]={},["code"]="\010    if unit=='player' or unit:match('^party[1-4]$') then return true end\010    local slot=unit:match('^raid(%d+)$');slot=slot and tonumber(slot)\010    return slot~=nil and slot>=1 and slot<=40 and unit=='raid'..tostring(slot)\010",["kind"]="function",["line"]=3,["parameters"]={"unit"}}},["hash"]="4872d2c8c67ba0a5471f32a2e167253c13cd7ce8c81020541933ef921f00a632"},["Platform/rotation_owner.lua"]={["bindings"]={["Platform_GetPlayerOwnerClassObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"}},["bindings"]={},["callName"]="addon.Platform:GetPlayerOwnerClassObservation",["code"]="\010    if type(UnitClass)~='function' then return nil,'missing-api' end\010    local ok,_,class=pcall(UnitClass,'player')\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(class) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(class) then return nil,'restricted-value' end\010    if class==nil then return nil,'class-data-unavailable' end\010    if type(class)~='string' or class=='' then return nil,'invalid-api-result' end\010    return class\010",["description"]="Read a fresh protected UnitClass player observation for rotation ownership. Consume only the readable nonempty class filename from return two. No existence, level, vehicle, family or combat-policy read is added, and no result persists across calls. Core ownership still validates the class token and character key separately; overridden context providers retain their complete original path.",["kind"]="function",["line"]=6,["parameters"]={"self"},["returns"]={{["description"]="Fresh readable class filename, or nil when unavailable.",["type"]="string | nil"},{["description"]="Capability or observation availability reason for a nil class.",["type"]="string | nil"}}}},["hash"]="08c7a34b88b8409cd479a430e8f66d3600cec8f31ee52eafa9a5784256fbd976"},["Platform/runes.lua"]={["bindings"]={["Platform_GetRuneCooldownObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Exact integral native rune slot from 1 through 6.",["name"]="index",["type"]="number"}},["bindings"]={["numberField"]="builtin:Platform/runes.lua:numberField",["validIndex"]="builtin:Platform/runes.lua:validIndex"},["callName"]="addon.Platform:GetRuneCooldownObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    local valid,reason=validIndex(self,index)\010    if not valid then return nil,reason end\010    local api=GetRuneCooldown\010    if type(api)~='function' then return nil,'missing-api' end\010    local ok,tuple=pcall(function() return {api(index)} end)\010    if not ok then return nil,'api-error' end\010    local record={}\010    record.start,record.startReason=numberField(self,tuple[1],'rune-start-unavailable')\010    record.duration,record.durationReason=numberField(self,tuple[2],'rune-duration-unavailable')\010    local ready=tuple[3]\010    if not self:CanReadValue(ready) then record.readyReason='restricted-value'\010    elseif ready==nil then record.readyReason='rune-ready-unavailable'\010    elseif type(ready)~='boolean' then record.readyReason='invalid-api-result'\010    else record.ready=ready end\010    return record\010",["description"]="Read one protected GetRuneCooldown tuple for an exact native slot. Normalize ready, start and duration independently: ready requires a readable Boolean, while each time requires a readable finite number and preserves signed, fractional and zero values. Every unavailable field carries its own reason. A successful empty tuple yields a partial record; missing capability, policy or native-call failure yields nil. Never infer ready from timing or timing from ready. Cache this complete record at the caller to share one observation between rune-count and cooldown predicates.",["kind"]="function",["line"]=36,["parameters"]={"self","index"},["returns"]={{["description"]="Partial record containing ready or readyReason, start or startReason, and duration or durationReason; nil only when the query itself is unavailable.",["type"]="table | nil"},{["description"]="Policy, slot-validation, capability or native-call availability reason for a nil record.",["type"]="string | nil"}}},["Platform_GetRuneEvaluationTime"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"}},["bindings"]={["numberField"]="builtin:Platform/runes.lua:numberField"},["callName"]="addon.Platform:GetRuneEvaluationTime",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    local api=GetTime\010    if type(api)~='function' then return nil,'missing-api' end\010    local ok,value=pcall(api)\010    if not ok then return nil,'api-error' end\010    return numberField(self,value,'rune-time-unavailable')\010",["description"]="Read a fresh protected zero-argument GetTime for rune cooldown arithmetic. Require a readable finite number. This observation is deliberately uncached; callers preserve the original clock-before-scan order and require its value only when a matching rune needs timing. No evaluation-start substitution or inferred time is supplied.",["kind"]="function",["line"]=56,["parameters"]={"self"},["returns"]={{["description"]="Fresh finite native clock value, or nil when unavailable.",["type"]="number | nil"},{["description"]="Policy, capability or clock observation availability reason for a nil time.",["type"]="string | nil"}}},["Platform_GetRuneTypeObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Exact integral native rune slot from 1 through 6.",["name"]="index",["type"]="number"}},["bindings"]={["numberField"]="builtin:Platform/runes.lua:numberField",["validIndex"]="builtin:Platform/runes.lua:validIndex"},["callName"]="addon.Platform:GetRuneTypeObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    local valid,reason=validIndex(self,index)\010    if not valid then return nil,reason end\010    local api=GetRuneType\010    if type(api)~='function' then return nil,'missing-api' end\010    local ok,value=pcall(api,index)\010    if not ok then return nil,'api-error' end\010    local runeType,why=numberField(self,value,'rune-type-unavailable')\010    if runeType==nil then return nil,why end\010    if runeType<=0 or runeType%1~=0 then return nil,'invalid-api-result' end\010    return runeType\010",["description"]="Observe one exact native rune slot using GetRuneType with its single index argument. Require a readable finite positive integral type; known future numeric types remain distinct from the selected type, and Death is an exact type rather than a wildcard. Missing, failed, restricted or malformed observations remain unavailable. No class, unit, count or inferred base-rune query is added.",["kind"]="function",["line"]=20,["parameters"]={"self","index"},["returns"]={{["description"]="Readable finite positive integral rune type, or nil when unavailable.",["type"]="number | nil"},{["description"]="Policy, slot-validation or required observation availability reason for a nil type.",["type"]="string | nil"}}},["finite"]={["bindings"]={},["code"]="\010    return type(value)=='number' and value==value and value<math.huge and value>-math.huge\010",["kind"]="function",["line"]=4,["parameters"]={"value"}},["numberField"]={["bindings"]={["finite"]="builtin:Platform/runes.lua:finite"},["code"]="\010    if not self:CanReadValue(value) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(value) then return nil,'restricted-value' end\010    if value==nil then return nil,missing end\010    if not finite(value) then return nil,'invalid-api-result' end\010    return value\010",["kind"]="function",["line"]=12,["parameters"]={"self","value","missing"}},["validIndex"]={["bindings"]={["finite"]="builtin:Platform/runes.lua:finite"},["code"]="\010    if not self:CanReadValue(index) then return nil,'restricted-value' end\010    if not finite(index) or index%1~=0 or index<1 or index>6 then return nil,'invalid-rune-index' end\010    return true\010",["kind"]="function",["line"]=7,["parameters"]={"self","index"}}},["hash"]="1b3d58a78948c75746073261675d39f0f3a63c42864e926b62cd4eea9770aeac"},["Platform/spells.lua"]={["bindings"]={["Platform_GetSpellCharges"]={["args"]={{["description"]="Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.",["name"]="self",["type"]="RMPlatform"},{["description"]="Spell ID or client-recognized spell name whose charges should be read.",["name"]="spell",["type"]="number | string"}},["bindings"]={["copy"]="builtin:Platform/spells.lua:copy",["identifier"]="builtin:Platform/spells.lua:identifier"},["callName"]="addon.Platform:GetSpellCharges",["code"]="\010    local valid,reason=identifier(spell)\010    if not valid then return nil,reason end\010    local ok,record\010    if C_Spell and type(C_Spell.GetSpellCharges)==\"function\" then\010        ok,record=pcall(C_Spell.GetSpellCharges,spell)\010    elseif type(GetSpellCharges)==\"function\" then\010        local current,maximum,start,duration,rate\010        ok,current,maximum,start,duration,rate=pcall(GetSpellCharges,spell)\010        if not ok then return nil,\"api-error\" end\010        record={currentCharges=current,maxCharges=maximum,cooldownStartTime=start,cooldownDuration=duration,chargeModRate=rate}\010    else return nil,\"missing-api\" end\010    if not ok then return nil,\"api-error\" end\010    if not self:CanReadValue(record) then return nil,\"restricted-value\" end\010    if record==nil then return nil,\"spell-charges-unavailable\" end\010    local charges,why=copy(record,{currentCharges=\"number\",maxCharges=\"number\",cooldownStartTime=\"number\",\010        cooldownDuration=\"number\",chargeModRate=\"number\",isActive=\"boolean\"})\010    if not charges then return nil,why end\010    if next(charges)==nil then return nil,\"spell-charges-unavailable\" end\010    local current,maximum,start,duration=charges.currentCharges,charges.maxCharges,charges.cooldownStartTime,charges.cooldownDuration\010    if current==nil or maximum==nil or start==nil or duration==nil or current<0 or current%1~=0\010        or maximum<1 or maximum%1~=0 or current>maximum or start<0 or duration<0\010        or charges.chargeModRate and charges.chargeModRate<=0 then return nil,\"invalid-api-result\" end\010    local active=current<maximum and start>0 and duration>0\010    if charges.isActive==nil then charges.isActive=active\010    elseif charges.isActive and not active then return nil,\"invalid-api-result\" end\010    charges.chargeModRate=charges.chargeModRate or 1\010    return charges\010",["description"]="Read a normalized charge record: currentCharges, maxCharges, cooldownStartTime, cooldownDuration, chargeModRate and isActive. Unsupported spells or restricted client data return nil with a reason.",["kind"]="function",["line"]=160,["parameters"]={"self","spell"},["returns"]={{["description"]="Readable charge record, or nil when unavailable.",["type"]="table | nil"},{["description"]="Availability or validation reason when the record is nil.",["type"]="string | nil"}}},["Platform_GetSpellCooldown"]={["args"]={{["description"]="Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.",["name"]="self",["type"]="RMPlatform"},{["description"]="Spell ID or client-recognized spell name whose cooldown should be read.",["name"]="spell",["type"]="number | string"}},["bindings"]={["copy"]="builtin:Platform/spells.lua:copy",["identifier"]="builtin:Platform/spells.lua:identifier"},["callName"]="addon.Platform:GetSpellCooldown",["code"]="\010    local valid, reason = identifier(spell)\010    if not valid then return nil, reason end\010    local ok, record\010    if C_Spell and type(C_Spell.GetSpellCooldown) == \"function\" then\010        ok, record = pcall(C_Spell.GetSpellCooldown, spell)\010    elseif type(GetSpellCooldown) == \"function\" then\010        local start, duration, enabled, rate\010        ok, start, duration, enabled, rate = pcall(GetSpellCooldown, spell)\010        if not ok then return nil, \"api-error\" end\010        for _, value in pairs({start=start, duration=duration, enabled=enabled, rate=rate}) do\010            if not self:CanReadValue(value) then return nil, \"restricted-value\" end\010        end\010        if start ~= nil then\010            if enabled ~= 0 and enabled ~= 1 then return nil, \"invalid-api-result\" end\010            record = {startTime=start, duration=duration, isEnabled=enabled == 1, modRate=rate or 1}\010        end\010    else return nil, \"missing-api\" end\010    if not ok then return nil, \"api-error\" end\010    if not self:CanReadValue(record) then return nil, \"restricted-value\" end\010    if record == nil then return nil, \"spell-data-unavailable\" end\010    local cooldown, why = copy(record, {startTime=\"number\", duration=\"number\", isEnabled=\"boolean\", modRate=\"number\"})\010    if not cooldown then return nil, why end\010    if cooldown.startTime == nil or cooldown.duration == nil or cooldown.isEnabled == nil\010        or cooldown.startTime < 0 or cooldown.duration < 0 or (cooldown.modRate and cooldown.modRate <= 0) then\010        return nil, \"invalid-api-result\"\010    end\010    cooldown.modRate = cooldown.modRate or 1\010    return cooldown\010",["description"]="Read and normalize a spell cooldown across supported clients. The returned record contains startTime, duration, isEnabled and modRate. The timestamps and duration already describe expiration in GetTime() seconds; do not divide them by modRate.",["kind"]="function",["line"]=87,["parameters"]={"self","spell"},["returns"]={{["description"]="Readable cooldown record, or nil when unavailable.",["type"]="table | nil"},{["description"]="Availability or validation reason when the record is nil.",["type"]="string | nil"}}},["Platform_IsAutoRepeatActive"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Positive integer spell ID, not a spell-book slot.",["name"]="spellID",["type"]="number"}},["bindings"]={["identifier"]="builtin:Platform/spells.lua:identifier"},["callName"]="addon.Platform:IsAutoRepeatActive",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    local valid,reason=identifier(spellID,true)\010    if not valid then return nil,reason end\010    local native=C_Spell and C_Spell.IsAutoRepeatSpell\010    local ok,active\010    if type(native)=='function' then\010        ok,active=pcall(native,spellID)\010    else\010        if type(IsAutoRepeatSpell)~='function' or type(FindSpellBookSlotBySpellID)~='function' then return nil,'missing-api' end\010        local found,slot=pcall(FindSpellBookSlotBySpellID,spellID,false)\010        if not found then return nil,'api-error' end\010        if not self:CanReadValue(slot) then return nil,'restricted-value' end\010        if slot==nil then return nil,'spell-not-in-book' end\010        if type(slot)~='number' or slot<1 or slot==math.huge or slot%1~=0 then return nil,'invalid-api-result' end\010        ok,active=pcall(IsAutoRepeatSpell,slot,BOOKTYPE_SPELL or 'spell')\010    end\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(active) then return nil,'restricted-value' end\010    if type(native)~='function' then\010        if active==0 then active=false elseif active==1 then active=true end\010    end\010    if type(active)~='boolean' then return nil,'invalid-api-result' end\010    return active\010",["description"]="Read the player auto-repeat state for a spell such as Shoot or Auto Shot. This is distinct from a current or queued cast. Modern clients receive the exact spell ID; a legacy query resolves the player spell-book slot first. Restricted client policies, unreadable results and unavailable book slots return nil with a reason. This observes state and never starts or stops a spell.",["kind"]="function",["line"]=209,["parameters"]={"self","spellID"},["returns"]={{["description"]="True when the client reports this spell auto-repeating; false when it reports inactive; nil when unavailable.",["type"]="boolean | nil"},{["description"]="Validation or availability reason for a nil result.",["type"]="string | nil"}}},["Platform_IsSpellReady"]={["args"]={{["description"]="Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.",["name"]="self",["type"]="RMPlatform"},{["description"]="Spell ID or client-recognized spell name whose cooldown should be checked.",["name"]="spell",["type"]="number | string"},{["description"]="Current evaluation time in seconds from GetTime(), normally evalStart.",["name"]="now",["type"]="number"}},["bindings"]={},["callName"]="addon.Platform:IsSpellReady",["code"]="\010    if not self:CanReadValue(now) then return nil, \"restricted-value\" end\010    if type(now)~=\"number\" or now~=now or now==math.huge or now==-math.huge then\010        return nil, \"invalid-time\"\010    end\010    local cooldown,reason=self:GetSpellCooldown(spell)\010    if not cooldown then return nil,reason end\010    if not cooldown.isEnabled then return false end\010    local expires=cooldown.startTime+cooldown.duration\010    if cooldown.duration==0 or expires<=now then return true end\010\010    local gcd,why=self:GetGlobalCooldown()\010    if not gcd then return nil,why end\010    if not gcd.isEnabled or gcd.duration==0 then return false end\010    -- modRate controls cooldown animation; API timestamps/duration already\010    -- describe expiration in GetTime seconds, so do not divide them by it.\010    local gcdExpires=gcd.startTime+gcd.duration\010    return gcdExpires>now and expires<=gcdExpires+0.001\010",["description"]="Check whether a spell can be recommended now, allowing a spell whose remaining cooldown ends with the current global cooldown. This checks cooldown readiness only; it does not check learned status, range or resource usability. Pass evaluation time from evalStart or GetTime().",["kind"]="function",["line"]=140,["parameters"]={"self","spell","now"},["returns"]={{["description"]="True when ready by the end of the global cooldown; false when its own cooldown prevents recommendation; nil when the client cannot supply a readable result.",["type"]="boolean | nil"},{["description"]="Availability or validation reason when the result is nil.",["type"]="string | nil"}}},["copy"]={["bindings"]={["platform"]="builtin:Platform/spells.lua:platform"},["code"]="\010    if not platform:CanReadValue(record) then return nil, \"restricted-value\" end\010    if type(record) ~= \"table\" then return nil, \"invalid-api-result\" end\010    local result = {}\010    for key, kind in pairs(fields) do\010        local value = record[key]\010        if not platform:CanReadValue(value) then return nil, \"restricted-value\" end\010        if value ~= nil then\010            if type(value) ~= kind and not (kind == \"icon\" and (type(value) == \"number\" or type(value) == \"string\")) then\010                return nil, \"invalid-api-result\"\010            end\010            if type(value) == \"number\" and (value ~= value or value == math.huge or value == -math.huge) then\010                return nil, \"invalid-api-result\"\010            end\010            result[key] = value\010        end\010    end\010    return result\010",["kind"]="function",["line"]=11,["parameters"]={"record","fields"}},["identifier"]={["bindings"]={["platform"]="builtin:Platform/spells.lua:platform"},["code"]="\010    if not platform:CanReadValue(value) then return false, \"restricted-value\" end\010    if type(value) == \"number\" and value > 0 and value < math.huge and value % 1 == 0 then return true end\010    if not idOnly and type(value) == \"string\" and #value > 0 then return true end\010    return false, \"invalid-spell\"\010",["kind"]="function",["line"]=4,["parameters"]={"value","idOnly"}},["platform"]={["kind"]="value"}},["hash"]="5949b51dfd644e8e4ba37e8da81726d7a7c1aca1382d4d7ef9e99a8f6314185e"},["Platform/threat.lua"]={["bindings"]={["Platform_GetUnitThreatObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Exact unit token used for existence and as the recipient of player hostility and threat queries.",["name"]="unit",["type"]="string"}},["bindings"]={},["callName"]="addon.Platform:GetUnitThreatObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local existsOk,exists=pcall(UnitExists,unit)\010    if not existsOk then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return false end\010    if type(UnitIsEnemy)~='function' then return nil,'missing-api' end\010    local enemyOk,enemy=pcall(UnitIsEnemy,'player',unit)\010    if not enemyOk then return nil,'api-error' end\010    if not self:CanReadValue(enemy) then return nil,'restricted-value' end\010    if enemy==nil then return nil,'unit-data-unavailable' end\010    if type(enemy)~='boolean' then return nil,'invalid-api-result' end\010    if not enemy then return false end\010    if type(UnitThreatSituation)~='function' then return nil,'missing-api' end\010    local threatOk,threat=pcall(UnitThreatSituation,'player',unit)\010    if not threatOk then return nil,'api-error' end\010    if not self:CanReadValue(threat) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(threat) then return nil,'restricted-value' end\010    if threat==nil then return false end\010    if type(threat)~='number' or threat~=threat or threat==math.huge or threat==-math.huge then return nil,'invalid-api-result' end\010    return threat\010",["description"]="Observe ordered selected-unit existence, hostility from player, then the player threat status on that unit. Known absence, nonenemy and a successfully read nil threat status return false, preserving the no-threat predicate. Finite status numbers including zero retain their original comparison meaning. Required missing, failed, nil, restricted or malformed facts return nil with a reason. No attackability, death, combat or vehicle inference is added.",["kind"]="function",["line"]=6,["parameters"]={"self","unit"},["returns"]={{["description"]="Finite native threat status, false for known absence/nonenemy/no-threat, or nil for unavailable observations.",["type"]="number | boolean | nil"},{["description"]="Policy, query-validation or availability reason for a nil threat observation.",["type"]="string | nil"}}}},["hash"]="3c4876c3ad0971680e220db8d8f8ab725f8df7a152302c030d9b3d5cfc208227"},["Platform/unit_attackability.lua"]={["bindings"]={["Platform_GetUnitAttackabilityObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Exact selected unit token; the attacker remains player.",["name"]="unit",["type"]="string"}},["bindings"]={},["callName"]="addon.Platform:GetUnitAttackabilityObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local existsOk,exists=pcall(UnitExists,unit)\010    if not existsOk then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return false end\010    if type(UnitCanAttack)~='function' then return nil,'missing-api' end\010    local attackOk,attack=pcall(UnitCanAttack,'player',unit)\010    if not attackOk then return nil,'api-error' end\010    if not self:CanReadValue(attack) then return nil,'restricted-value' end\010    if attack==nil then return nil,'attackability-data-unavailable' end\010    if type(attack)~='boolean' then return nil,'invalid-api-result' end\010    if not attack then return false end\010    if type(UnitIsDead)~='function' then return nil,'missing-api' end\010    local deadOk,dead=pcall(UnitIsDead,unit)\010    if not deadOk then return nil,'api-error' end\010    if not self:CanReadValue(dead) then return nil,'restricted-value' end\010    if dead==nil then return nil,'death-data-unavailable' end\010    if type(dead)~='boolean' then return nil,'invalid-api-result' end\010    return not dead\010",["description"]="Observe whether the player can attack a selected unit that is not dead, using the exact UnitExists, UnitCanAttack and UnitIsDead predicates. Known absence or a readable false attack result returns false without querying death. Required missing, failed, restricted or malformed observations return nil with a reason. This does not test ghosts, range, hostility or ability usability, and does not redirect unit ownership.",["kind"]="function",["line"]=6,["parameters"]={"self","unit"},["returns"]={{["description"]="True for a readable attackable non-dead unit, false for a conclusive negative result, or nil when a required observation is unavailable.",["type"]="boolean | nil"},{["description"]="Policy, query-validation or availability reason for nil attackability.",["type"]="string | nil"}}}},["hash"]="dc5d6660e36bff0ee37c9592782846f5ea5db15f25e71cc56c9d6c6f0c3d4bc2"},["Platform/unit_flags.lua"]={["bindings"]={["Platform_GetUnitFlagObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Exact unit token whose selected flag should be observed.",["name"]="unit",["type"]="string"},{["description"]="One of combat, enemy or pvp; other flag kinds are not supported.",["name"]="kind",["type"]="string"}},["bindings"]={},["callName"]="addon.Platform:GetUnitFlagObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) or not self:CanReadValue(kind) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if kind~='combat' and kind~='enemy' and kind~='pvp' then return nil,'invalid-unit-flag-query' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local existsOk,exists=pcall(UnitExists,unit)\010    if not existsOk then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return false end\010    local api\010    if kind=='combat' then api=UnitAffectingCombat\010    elseif kind=='enemy' then api=UnitIsEnemy\010    else api=UnitIsPVP end\010    if type(api)~='function' then return nil,'missing-api' end\010    local ok,result\010    if kind=='enemy' then ok,result=pcall(api,'player',unit)\010    else ok,result=pcall(api,unit) end\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(result) then return nil,'restricted-value' end\010    if result==nil then return nil,'unit-flag-unavailable' end\010    if type(result)~='boolean' then return nil,'invalid-api-result' end\010    return result\010",["description"]="Observe one current unit flag: combat uses UnitAffectingCombat, enemy uses UnitIsEnemy with player as the first unit, and pvp uses UnitIsPVP. A readable absent unit returns false without querying the flag. Required missing, failed, restricted or malformed observations return nil with a reason. This preserves the exact selected unit and does not infer friendliness, attackability or other unit states.",["kind"]="function",["line"]=6,["parameters"]={"self","unit","kind"},["returns"]={{["description"]="Readable selected flag, false for a known absent unit, or nil when a required observation is unavailable.",["type"]="boolean | nil"},{["description"]="Policy, query-validation or availability reason for a nil unit flag.",["type"]="string | nil"}}}},["hash"]="ff7421385edf6d8b85a0420e9b3c13fc61f83916736dfbb53dcc4c8ff19a8fad"},["Platform/unit_health.lua"]={["bindings"]={["Platform_GetUnitHealthObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Unit token whose current health should be observed.",["name"]="unit",["type"]="string"},{["description"]="True also observes maximum health; false or nil reads current health only.",["name"]="includeMaximum",["type"]="boolean | nil"}},["bindings"]={["finite"]="builtin:Platform/unit_health.lua:finite"},["callName"]="addon.Platform:GetUnitHealthObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) or not self:CanReadValue(includeMaximum) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if includeMaximum~=nil and type(includeMaximum)~='boolean' then return nil,'invalid-health-query' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local existsOk,exists=pcall(UnitExists,unit)\010    if not existsOk then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return {exists=false} end\010    if type(UnitHealth)~='function' then return nil,'missing-api' end\010    local currentOk,current=pcall(UnitHealth,unit)\010    if not currentOk then return nil,'api-error' end\010    if not self:CanReadValue(current) then return nil,'restricted-value' end\010    -- Keep the native proof visible at the arithmetic boundary; the platform\010    -- guard above also covers older clients and the issecretvalue predicate.\010    if canaccessvalue and not canaccessvalue(current) then return nil,'restricted-value' end\010    if current==nil then return nil,'health-data-unavailable' end\010    if not finite(current) or current<0 then return nil,'invalid-api-result' end\010    local record={exists=true,current=current}\010    if includeMaximum then\010        if type(UnitHealthMax)~='function' then return nil,'missing-api' end\010        local maximumOk,maximum=pcall(UnitHealthMax,unit)\010        if not maximumOk then return nil,'api-error' end\010        if not self:CanReadValue(maximum) then return nil,'restricted-value' end\010        if canaccessvalue and not canaccessvalue(maximum) then return nil,'restricted-value' end\010        if maximum==nil then return nil,'health-data-unavailable' end\010        if not finite(maximum) or maximum<0 then return nil,'invalid-api-result' end\010        record.maximum=maximum\010    end\010    return record\010",["description"]="Observe readable current health and optionally maximum health on supported clients. A readable absent unit returns exists=false. Missing, failed, restricted or malformed observations return nil with a reason; they do not establish an absent unit or a health value.",["kind"]="function",["line"]=10,["parameters"]={"self","unit","includeMaximum"},["returns"]={{["description"]="Fresh readable record with exists and, when present, current health. Maximum health is included only when requested.",["type"]="table | nil"},{["description"]="Policy, validation or availability reason for a nil health observation.",["type"]="string | nil"}}},["finite"]={["bindings"]={},["code"]="\010    return type(value)=='number' and value==value and value<math.huge and value>-math.huge\010",["kind"]="function",["line"]=4,["parameters"]={"value"}}},["hash"]="dc2ecdf6855609a696d449494ee131246edf21fc63d4cfcbb73938602c5e15a9"},["Platform/unit_identity.lua"]={["bindings"]={["Platform_GetUnitIdentityObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="First exact unit token, checked for existence before comparison.",["name"]="unit",["type"]="string"},{["description"]="Second exact unit token, passed unchanged to UnitIsUnit.",["name"]="otherunit",["type"]="string"}},["bindings"]={},["callName"]="addon.Platform:GetUnitIdentityObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) or not self:CanReadValue(otherunit) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' or type(otherunit)~='string' or otherunit=='' then return nil,'invalid-unit' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local existsOk,exists=pcall(UnitExists,unit)\010    if not existsOk then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return false end\010    if type(UnitIsUnit)~='function' then return nil,'missing-api' end\010    local ok,same=pcall(UnitIsUnit,unit,otherunit)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(same) then return nil,'restricted-value' end\010    if same==nil then return nil,'unit-identity-unavailable' end\010    if type(same)~='boolean' then return nil,'invalid-api-result' end\010    return same\010",["description"]="Compare two exact unit tokens using UnitIsUnit after checking only the first token with UnitExists. A readable absent first unit returns false without comparing. Required missing, failed, restricted or malformed observations return nil with a reason. No second existence query, GUID lookup or inferred identity is added.",["kind"]="function",["line"]=6,["parameters"]={"self","unit","otherunit"},["returns"]={{["description"]="Readable unit equality, false for a known absent first unit, or nil when required observations are unavailable.",["type"]="boolean | nil"},{["description"]="Policy, token-validation or availability reason for a nil identity result.",["type"]="string | nil"}}}},["hash"]="94517efae16237ad538d925dc071fdad0c68e454b372c31c810df639ddf09638"},["Platform/unit_level.lua"]={["bindings"]={["Platform_GetUnitLevelObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Unit token whose raw level should be observed.",["name"]="unit",["type"]="string"}},["bindings"]={["finite"]="builtin:Platform/unit_level.lua:finite"},["callName"]="addon.Platform:GetUnitLevelObservation",["code"]="\010    if not self:CanReadValue(unit) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if self:GetClientInfo().family=='unknown' then return nil,'unsupported-client' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local existsOk,exists=pcall(UnitExists,unit)\010    if not existsOk then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return {exists=false} end\010    if type(UnitLevel)~='function' then return nil,'missing-api' end\010    local levelOk,level=pcall(UnitLevel,unit)\010    if not levelOk then return nil,'api-error' end\010    if not self:CanReadValue(level) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(level) then return nil,'restricted-value' end\010    if level==nil then return nil,'level-data-unavailable' end\010    if not finite(level) then return nil,'invalid-api-result' end\010    if level<0 then return nil,'level-data-unavailable' end\010    if level==0 or level%1~=0 then return nil,'invalid-api-result' end\010    return {exists=true,level=level}\010",["description"]="Observe a readable raw unit level on known clients. A readable absent unit returns exists=false; present units require a positive finite integer UnitLevel. Unknown boss levels, missing, failed, restricted or malformed observations return nil with a reason. This does not use effective or scaled levels.",["kind"]="function",["line"]=10,["parameters"]={"self","unit"},["returns"]={{["description"]="Fresh readable record with exists and, when present, a positive integer level.",["type"]="table | nil"},{["description"]="Availability or query-validation reason for a nil level observation.",["type"]="string | nil"}}},["finite"]={["bindings"]={},["code"]="\010    return type(value)=='number' and value==value and value<math.huge and value>-math.huge\010",["kind"]="function",["line"]=4,["parameters"]={"value"}}},["hash"]="b7392d1093d672499ba0f5e57afb48e4e01121699c97476e6d0e2cb2d0114c27"},["Platform/unit_metadata.lua"]={["bindings"]={["Platform_GetUnitMetadataObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Exact unit token checked for existence and passed to the selected metadata API.",["name"]="unit",["type"]="string"},{["description"]="One of class, creature or classification; other metadata kinds are unsupported.",["name"]="kind",["type"]="string"}},["bindings"]={},["callName"]="addon.Platform:GetUnitMetadataObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) or not self:CanReadValue(kind) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if kind~='class' and kind~='creature' and kind~='classification' then return nil,'invalid-unit-metadata-query' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local existsOk,exists=pcall(UnitExists,unit)\010    if not existsOk then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return false end\010    local api\010    if kind=='class' then api=UnitClass\010    elseif kind=='creature' then api=UnitCreatureType\010    else api=UnitClassification end\010    if type(api)~='function' then return nil,'missing-api' end\010    local ok,observed\010    if kind=='class' then ok,observed=pcall(function() return select(2,api(unit)) end)\010    else ok,observed=pcall(api,unit) end\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(observed) then return nil,'restricted-value' end\010    if observed==nil then return nil,'unit-metadata-unavailable' end\010    if type(observed)~='string' or observed=='' then return nil,'invalid-api-result' end\010    return observed\010",["description"]="Observe one consumed native unit metadata field after checking UnitExists: class uses UnitClass return two, creature uses the localized UnitCreatureType name, and classification uses UnitClassification. A readable absent unit returns false without querying metadata. Unused tuple fields do not affect availability; a required missing, failed, nil, restricted or malformed value returns nil with a reason. No player class, GUID, enum or translation inference is added.",["kind"]="function",["line"]=6,["parameters"]={"self","unit","kind"},["returns"]={{["description"]="Readable consumed metadata string, false for a known absent unit, or nil when required data is unavailable.",["type"]="string | boolean | nil"},{["description"]="Policy, query-validation or availability reason for a nil metadata observation.",["type"]="string | nil"}}}},["hash"]="81dc74908aabee0b2b376a611a7bc7215db3eaa635212d87c42969187393e7a1"},["Platform/unit_power.lua"]={["bindings"]={["Platform_GetUnitPowerObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Exact unit token whose resource should be observed; this does not redirect player or vehicle units.",["name"]="unit",["type"]="string"},{["description"]="mana selects the explicit live Mana enum; current reads and forwards the actual UnitPowerType identity, including Mana zero.",["name"]="resource",["type"]="string"},{["description"]="True also observes the selected resource maximum; false or nil reads current quantity only.",["name"]="includeMaximum",["type"]="boolean | nil"}},["bindings"]={["finite"]="builtin:Platform/unit_power.lua:finite"},["callName"]="addon.Platform:GetUnitPowerObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) or not self:CanReadValue(resource) or not self:CanReadValue(includeMaximum) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if resource~='mana' and resource~='current' then return nil,'invalid-power-query' end\010    if includeMaximum~=nil and type(includeMaximum)~='boolean' then return nil,'invalid-power-query' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local existsOk,exists=pcall(UnitExists,unit)\010    if not existsOk then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return {exists=false} end\010    if not self:CanReadValue(Enum) then return nil,'restricted-value' end\010    if type(Enum)~='table' then return nil,'power-type-unavailable' end\010    local types=Enum.PowerType\010    if not self:CanReadValue(types) then return nil,'restricted-value' end\010    if type(types)~='table' then return nil,'power-type-unavailable' end\010    local powerType\010    if resource=='mana' then\010        powerType=types.Mana\010    else\010        if type(UnitPowerType)~='function' then return nil,'missing-api' end\010        local ok\010        ok,powerType=pcall(UnitPowerType,unit)\010        if not ok then return nil,'api-error' end\010    end\010    if not self:CanReadValue(powerType) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(powerType) then return nil,'restricted-value' end\010    if powerType==nil then return nil,'power-type-unavailable' end\010    if not finite(powerType) or powerType<0 or powerType%1~=0 then return nil,'invalid-api-result' end\010    local known=false\010    for _,id in pairs(types) do\010        if self:CanReadValue(id) and type(id)=='number' and id==powerType then known=true;break end\010    end\010    if not known then return nil,'power-type-unavailable' end\010    if type(UnitPower)~='function' then return nil,'missing-api' end\010    local currentOk,current=pcall(UnitPower,unit,powerType)\010    if not currentOk then return nil,'api-error' end\010    if not self:CanReadValue(current) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(current) then return nil,'restricted-value' end\010    if current==nil then return nil,'power-data-unavailable' end\010    if not finite(current) or resource=='mana' and current<0 then return nil,'invalid-api-result' end\010    local record={exists=true,powerType=powerType,current=current}\010    if includeMaximum then\010        if type(UnitPowerMax)~='function' then return nil,'missing-api' end\010        local maximumOk,maximum=pcall(UnitPowerMax,unit,powerType)\010        if not maximumOk then return nil,'api-error' end\010        if not self:CanReadValue(maximum) then return nil,'restricted-value' end\010        if canaccessvalue and not canaccessvalue(maximum) then return nil,'restricted-value' end\010        if maximum==nil then return nil,'power-data-unavailable' end\010        if not finite(maximum) or maximum<0 then return nil,'invalid-api-result' end\010        record.maximum=maximum\010    end\010    return record\010",["description"]="Observe explicit mana or the current raw power resource on supported readable clients. Select resource identities from the live PowerType enum; explicit mana never falls back to the current bar. Known absence returns exists=false; missing, failed, restricted or malformed observations return nil with a reason. Current-mode quantities preserve signed native resources; explicit mana is nonnegative. Request maximum only when needed; percentage consumers must require a positive maximum.",["kind"]="function",["line"]=10,["parameters"]={"self","unit","resource","includeMaximum"},["returns"]={{["description"]="Fresh readable record with exists and, when present, powerType and finite current quantity. Requested maximum is finite and nonnegative. Quantities may be fractional; current-mode current may be signed.",["type"]="table | nil"},{["description"]="Policy, query-validation or availability reason for a nil resource observation.",["type"]="string | nil"}}},["finite"]={["bindings"]={},["code"]="\010    return type(value)=='number' and value==value and value<math.huge and value>-math.huge\010",["kind"]="function",["line"]=4,["parameters"]={"value"}}},["hash"]="76e7ed6f2f02b6f4d97a687c16289b5f952c18fcf016d357f3a106c2dd5702d2"},["Platform/unit_stat.lua"]={["bindings"]={["Platform_GetUnitStatObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Selected nonempty unit token, unchanged in native calls.",["name"]="unit",["type"]="string"},{["description"]="Integral RM statistic selector 1..5, or 6 for effective armor.",["name"]="stat",["type"]="number"}},["bindings"]={["finite"]="builtin:Platform/unit_stat.lua:finite"},["callName"]="addon.Platform:GetUnitStatObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) or not self:CanReadValue(stat) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if not finite(stat) or stat%1~=0 or stat<1 or stat>6 then return nil,'invalid-stat-query' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local existsOk,exists=pcall(UnitExists,unit)\010    if not existsOk then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return {exists=false} end\010    local fn\010    if stat==6 then fn=UnitArmor else fn=UnitStat end\010    if type(fn)~='function' then return nil,'missing-api' end\010    local ok,_,effective\010    if stat==6 then ok,_,effective=pcall(fn,unit)\010    else ok,_,effective=pcall(fn,unit,stat) end\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(effective) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(effective) then return nil,'restricted-value' end\010    if effective==nil then return nil,'stat-data-unavailable' end\010    if not finite(effective) then return nil,'invalid-api-result' end\010    return {exists=true,value=effective}\010",["description"]="Observe the effective statistic from native return two only. On probe-policy clients query exact UnitExists(unit), then UnitStat(unit,stat) for selector 1..5 or UnitArmor(unit) for selector 6. Known absence returns exists=false; missing, failed, restricted or nonfinite required facts return nil. Preserve finite signed, fractional and zero values; ignore all unused tuple fields. The 1..6 route is an RM selector policy, not a native value-domain limit.",["kind"]="function",["line"]=9,["parameters"]={"self","unit","stat"},["returns"]={{["description"]="Record with exists=false, or exists=true and finite value; nil when unavailable.",["type"]="table | nil"},{["description"]="Query, policy or observation availability reason.",["type"]="string | nil"}}},["finite"]={["bindings"]={},["code"]="\010    return type(value)=='number' and value==value and value~=math.huge and value~=-math.huge\010",["kind"]="function",["line"]=3,["parameters"]={"value"}}},["hash"]="08e26273a325e377ec87ec6687c90ae7ebb1a70c34d001ac7c1f0379e063e63e"},["Platform/zone_pvp.lua"]={["bindings"]={["Platform_GetZonePVPObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"}},["bindings"]={},["callName"]="addon.Platform:GetZonePVPObservation",["code"]="\010    local family=self:GetClientInfo().family\010    if family~='retail' and family~='forever' and family~='era' and family~='tbc' and family~='progression' then return nil,'unsupported-policy' end\010    local namespace=C_PvP\010    if not self:CanReadValue(namespace) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(namespace) then return nil,'restricted-value' end\010    local api\010    if type(namespace)=='table' then api=namespace.GetZonePVPInfo end\010    if not self:CanReadValue(api) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(api) then return nil,'restricted-value' end\010    if type(api)~='function' then\010        api=GetZonePVPInfo\010        if not self:CanReadValue(api) then return nil,'restricted-value' end\010        if canaccessvalue and not canaccessvalue(api) then return nil,'restricted-value' end\010        if type(api)~='function' then return nil,'missing-api' end\010    end\010    local ok,pvpType=pcall(api)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(pvpType) then return nil,'restricted-value' end\010    if canaccessvalue and not canaccessvalue(pvpType) then return nil,'restricted-value' end\010    if pvpType==nil then return {} end\010    if type(pvpType)~='string' then return nil,'invalid-api-result' end\010    return {pvpType=pvpType}\010",["description"]="Observe the first zone PvP classification result with one protected zero-argument dot call. Prefer callable C_PvP.GetZonePVPInfo and use the global helper only when the modern callable is absent. A successful nil or no returned values produces a known empty record; missing, failed, restricted or malformed observations remain unavailable. Readable empty and future strings retain their exact meaning, and unused return fields do not determine availability. Never switch backends after a modern result or failure.",["kind"]="function",["line"]=5,["parameters"]={"self"},["returns"]={{["description"]="Successful observation record with pvpType string or nil; nil record means unavailable.",["type"]="table | nil"},{["description"]="Client-policy, capability, call or observation availability reason for a nil record.",["type"]="string | nil"}}}},["hash"]="cced093dcb695fa72e450bdb31a9ca0ef884167b1b59b98a2577eb50a65114e0"},["UI/checkbox.lua"]={["bindings"]={["CreateConditionCheckBox"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["constructor"]="builtin:UI/checkbox.lua:constructor"},["callName"]="addon:CreateConditionCheckBox",["code"]="\010    local widget=addon:AcquireConditionWidget('RM-CheckBox',constructor)\010    ---@cast widget RMConditionCheckBox\010    return widget\010",["description"]="Create a native boolean condition control. Configure SetLabel, SetValue, SetDisabled and OnValueChanged; add it with parent:AddChild(widget).",["kind"]="function",["line"]=28,["parameters"]={"self"},["returns"]={{["description"]="Checkbox widget with boolean value and callback methods.",["type"]="RMConditionCheckBox"}}},["constructor"]={["bindings"]={},["code"]="\010    local w={type='RM-CheckBox',alive=false,disabled=false}\010    local frame=CreateFrame('Frame',nil,UIParent);w.frame=frame;frame:SetSize(180,24)\010    local button=addon:CreateWorkbenchCheckBox(frame,'',180);w.button=button;button:SetAllPoints(frame)\010    function w:OnAcquire() self.alive=true;self:SetLabel('');self:SetValue(false);self:SetDisabled(false);self:SetWidth(180);self:SetHeight(24) end\010    function w:OnRelease() self.alive=false;self:SetValue(false) end\010    function w:SetLabel(text) button:SetText(text or '') end\010    function w:SetValue(value) button:SetChecked(value==true) end\010    function w:GetValue() return button:GetChecked() end\010    function w:SetDisabled(value) self.disabled=value==true;if self.disabled then button:Disable();button:SetAlpha(.45) else button:Enable();button:SetAlpha(1) end end\010    function w:OnWidthSet(width) button:GetFontString():SetWidth(math.max(1,width-22)) end\010    addon:SetUIScript(button,'OnClick',function()\010        if not w.alive or w.disabled then return end\010        w:SetValue(not w:GetValue());w:Fire('OnValueChanged',w:GetValue())\010    end)\010    ---@cast w RMConditionWidget\010    return addon:RegisterConditionWidget(w)\010",["kind"]="function",["line"]=9,["parameters"]={}}},["hash"]="fbc3bbaa9d668b676860ba5a20564e5fda12f586045611e8794a3e0ae3abeba4"},["UI/condition_display.lua"]={["bindings"]={["CreateConditionButton"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["buttonConstructor"]="builtin:UI/condition_display.lua:buttonConstructor"},["callName"]="addon:CreateConditionButton",["code"]=" return self:AcquireConditionWidget('RM-ConditionButton',buttonConstructor) ",["description"]="Create a native button using the shared condition widget lifecycle and workbench theme. SetText, SetDisabled and SetCallback configure its label and interaction; OnClick receives the mouse button. Add it to the supplied parent.",["kind"]="function",["line"]=120,["parameters"]={"self"},["returns"]={{["description"]="Native button with label, disabled state and lease-protected callbacks.",["type"]="RMConditionButton"}}},["CreateConditionLabel"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["labelConstructor"]="builtin:UI/condition_display.lua:labelConstructor"},["callName"]="addon:CreateConditionLabel",["code"]=" return self:AcquireConditionWidget('RM-ConditionLabel',labelConstructor) ",["description"]="Create native wrapping text that measures its height from its width and font. SetText, SetFont or SetFontObject configure its contents. Add it to the supplied parent so layout can track its measured height.",["kind"]="function",["line"]=118,["parameters"]={"self"},["returns"]={{["description"]="Native wrapping text control with font, color and alignment methods.",["type"]="RMConditionLabel"}}},["CreateConditionLink"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["labelConstructor"]="builtin:UI/condition_display.lua:labelConstructor"},["callName"]="addon:CreateConditionLink",["code"]=" return self:AcquireConditionWidget('RM-ConditionLink',function() return labelConstructor(true) end) ",["description"]="Create native wrapping text with optional leading image and pointer callbacks. SetImage and SetImageSize configure the image; OnEnter, OnLeave and OnClick use the condition callback contract. Add it to the supplied parent; callbacks expire when its lease is released.",["kind"]="function",["line"]=128,["parameters"]={"self"},["returns"]={{["description"]="Native interactive text and image control with measured height and disabled state.",["type"]="RMConditionLink"}}},["buttonConstructor"]={["bindings"]={["defaultFont"]="builtin:UI/condition_display.lua:defaultFont"},["code"]="\010    local w={type='RM-ConditionButton',text='',disabled=false,autoWidth=false}\010    local frame=addon:CreateWorkbenchButton(UIParent,'',200);w.frame=frame\010    local label=frame:GetFontString();w.label=label;label:SetWordWrap(false)\010    local enter,leave=frame:GetScript('OnEnter'),frame:GetScript('OnLeave')\010    function w:OnWidthSet(width) label:SetWidth(math.max(1,width-12)) end\010    function w:SetText(text)\010        self.text=text==nil and '' or tostring(text);frame:SetText(self.text);label:SetText(self.text)\010        if self.autoWidth then self:SetWidth(label:GetStringWidth()+30) end\010    end\010    function w:SetAutoWidth(value)\010        self.autoWidth=value==true\010        if self.autoWidth then self:SetWidth(label:GetStringWidth()+30) end\010    end\010    function w:SetDisabled(value) self.disabled=value==true;if self.disabled then frame:Disable() else frame:Enable() end end\010    function w:OnAcquire()\010        self:SetAutoWidth(false);self:SetWidth(200);self:SetHeight(24);self:SetDisabled(false);self:SetText('')\010        label:SetFontObject(defaultFont());frame:SetSelected(false);frame.tooltip=nil;frame:RegisterForClicks('LeftButtonUp')\010        local lease=self.rmLease\010        local function live() return w.rmActive and w.rmLease==lease and not w:IsReleasing() end\010        addon:SetUIScript(frame,'OnClick',function(_,button) if live() and not w.disabled then w:Fire('OnClick',button) end end)\010        addon:SetUIScript(frame,'OnEnter',function() if live() then if enter then enter(frame) end;w:Fire('OnEnter') end end)\010        addon:SetUIScript(frame,'OnLeave',function() if live() then if leave then leave(frame) end;w:Fire('OnLeave') end end)\010    end\010    function w:OnRelease()\010        if GameTooltip and GameTooltip:IsOwned(frame) then GameTooltip:Hide() end\010        self.text='';frame:SetText('');label:SetText('');frame.tooltip=nil\010    end\010    return addon:RegisterConditionWidget(w)\010",["kind"]="function",["line"]=86,["parameters"]={}},["defaultFont"]={["bindings"]={},["code"]=" return GameFontHighlightSmall or 'GameFontHighlightSmall' ",["kind"]="function",["line"]=2,["parameters"]={}},["labelConstructor"]={["bindings"]={["defaultFont"]="builtin:UI/condition_display.lua:defaultFont"},["code"]="\010    local w={type=interactive and 'RM-ConditionLink' or 'RM-ConditionLabel',text=''}\010    local frame=CreateFrame(interactive and 'Button' or 'Frame',nil,UIParent);w.frame=frame\010    local image=interactive and frame:CreateTexture(nil,'ARTWORK');w.image=image\010    local label=frame:CreateFontString(nil,'OVERLAY','GameFontHighlightSmall');w.label=label\010    label:SetPoint('TOPLEFT');label:SetWordWrap(true);label:SetHeight(0)\010    local function layoutText()\010        local inset=image and w.imagePath and (w.imageWidth+4) or 0\010        label:SetWidth(math.max(1,frame:GetWidth()-inset))\010        local textHeight=math.max(1,label:GetStringHeight() or 0)\010        local height=math.max(textHeight,image and w.imagePath and w.imageHeight or 0)\010        label:ClearAllPoints();label:SetPoint('TOPLEFT',frame,'TOPLEFT',inset,-(height-textHeight)/2)\010        if image then image:ClearAllPoints();image:SetPoint('TOPLEFT',frame,'TOPLEFT',0,-(height-w.imageHeight)/2) end\010        -- Backing frame dimensions may be quantized. Compare text requests,\010        -- not engine rounding, before notifying the parent layout.\010        local changed=height~=w.measuredHeight\010        w.measuredHeight=height;w:SetHeight(height)\010        return changed\010    end\010    local function measure()\010        if w.measuring then return end\010        w.measuring=true\010        local ok,changed=pcall(layoutText)\010        w.measuring=false\010        if not ok then error(changed,0) end\010        if changed and w.parent and w.parent.DoLayout then w.parent:DoLayout() end\010    end\010    function w:OnWidthSet() measure() end\010    function w:SetText(text) self.text=text==nil and '' or tostring(text);label:SetText(self.text);measure() end\010    function w:SetFont(path,height,flags) label:SetFont(path,height,flags);measure() end\010    function w:SetFontObject(font) label:SetFontObject(font or defaultFont());measure() end\010    function w:SetColor(red,green,blue,alpha)\010        if red==nil or green==nil or blue==nil then red,green,blue=1,1,1 end\010        label:SetTextColor(red,green,blue,alpha or 1)\010    end\010    function w:SetJustifyH(value) label:SetJustifyH(value) end\010    function w:SetJustifyV(value) label:SetJustifyV(value) end\010    if interactive then\010        function w:SetImage(path,...)\010            self.imagePath=path;image:SetTexture(path)\010            local count=select('#',...);if count==4 or count==8 then image:SetTexCoord(...) else image:SetTexCoord(0,1,0,1) end\010            if path then image:Show() else image:Hide() end;measure()\010        end\010        function w:SetImageSize(width,height) self.imageWidth,self.imageHeight=width,height;image:SetSize(width,height);measure() end\010        function w:SetDisabled(value) self.disabled=value==true;if self.disabled then frame:Disable() else frame:Enable() end end\010    end\010    function w:OnAcquire()\010        self.measuring=false;self.measuredHeight=nil\010        if interactive then self.imagePath=nil;self.imageWidth,self.imageHeight=24,24;image:SetTexture(nil);image:SetSize(24,24);image:Hide();self:SetDisabled(false) end\010        self:SetText('');self:SetFontObject();self:SetColor();self:SetJustifyH('LEFT');self:SetJustifyV('TOP');self:SetWidth(200)\010        if interactive then\010            frame:RegisterForClicks('LeftButtonUp','RightButtonUp');local lease=self.rmLease\010            local function live() return w.rmActive and w.rmLease==lease and not w:IsReleasing() end\010            addon:SetUIScript(frame,'OnEnter',function() if live() then w:Fire('OnEnter') end end)\010            addon:SetUIScript(frame,'OnLeave',function() if live() then w:Fire('OnLeave') end end)\010            addon:SetUIScript(frame,'OnClick',function(_,button) if live() and not w.disabled then w:Fire('OnClick',button) end end)\010        end\010    end\010    function w:OnRelease()\010        self.text='';self.measuring=false;self.measuredHeight=nil;label:SetText('')\010        if image then image:Hide();image:SetTexture(nil);self.imagePath=nil;if GameTooltip and GameTooltip:IsOwned(frame) then GameTooltip:Hide() end end\010    end\010    return addon:RegisterConditionWidget(w)\010",["kind"]="function",["line"]=13,["parameters"]={"interactive"}}},["hash"]="bb3555fe6a582d07c9edb618753df59e57141c1aedddaf6b085b41d823974cfa"},["UI/condition_icon.lua"]={["bindings"]={["CreateConditionIcon"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["constructor"]="builtin:UI/condition_icon.lua:constructor"},["callName"]="addon:CreateConditionIcon",["code"]="\010    return self:AcquireConditionWidget('RM-ConditionIcon',constructor)\010",["description"]="Create a native image control using the condition widget lifecycle. SetImage and SetImageSize choose the texture; SetText optionally adds a caption. OnClick, OnEnter and OnLeave use the shared callback contract. Add the control to the supplied parent.",["kind"]="function",["line"]=56,["parameters"]={"self"},["returns"]={{["description"]="Native image control with label, texture, disabled state and callbacks.",["type"]="RMConditionIcon"}}},["constructor"]={["bindings"]={},["code"]="\010    local w={type='RM-ConditionIcon',alive=false,disabled=false}\010    local frame=CreateFrame('Button',nil,UIParent);w.frame=frame;frame:EnableMouse(true)\010    local image=frame:CreateTexture(nil,'ARTWORK');w.image=image;image:SetPoint('TOP',0,-5)\010    local label=frame:CreateFontString(nil,'OVERLAY','GameFontHighlightSmall');w.label=label\010    label:SetPoint('BOTTOMLEFT');label:SetPoint('BOTTOMRIGHT');label:SetJustifyH('CENTER');label:SetJustifyV('TOP');label:SetHeight(18)\010    function w:SetLabel(text)\010        self.labelText=text or '';label:SetText(self.labelText)\010        if self.labelText~='' then label:Show() else label:Hide() end\010        self:SetHeight(image:GetHeight()+(self.labelText~='' and 25 or 10))\010    end\010    function w:SetText(text) self:SetLabel(text) end\010    function w:SetImage(path,...)\010        image:SetTexture(path)\010        local count=select('#',...)\010        if count==4 or count==8 then image:SetTexCoord(...) else image:SetTexCoord(0,1,0,1) end\010    end\010    function w:SetImageByAtlas(atlas) image:SetAtlas(atlas) end\010    function w:SetImageSize(width,height)\010        image:SetSize(width,height);self:SetHeight(height+(self.labelText~='' and 25 or 10))\010    end\010    function w:SetDisabled(value)\010        self.disabled=value==true\010        if self.disabled then frame:Disable();image:SetVertexColor(.5,.5,.5,.5);label:SetTextColor(.5,.5,.5)\010        else frame:Enable();image:SetVertexColor(1,1,1,1);label:SetTextColor(1,1,1) end\010    end\010    function w:OnAcquire()\010        self.alive=true;self:SetWidth(110);self:SetLabel('');self:SetImage(nil);self:SetImageSize(64,64);self:SetDisabled(false)\010        frame:RegisterForClicks('LeftButtonUp')\010        local lease=self.rmLease\010        local function live() return w.alive and w.rmActive and w.rmLease==lease and not w:IsReleasing() end\010        addon:SetUIScript(frame,'OnClick',function(_,button) if live() and not w.disabled then w:Fire('OnClick',button) end end)\010        addon:SetUIScript(frame,'OnEnter',function() if live() then w:Fire('OnEnter') end end)\010        addon:SetUIScript(frame,'OnLeave',function() if live() then w:Fire('OnLeave') end end)\010    end\010    function w:OnRelease()\010        self.alive=false\010        if GameTooltip and GameTooltip:IsOwned(frame) then GameTooltip:Hide() end\010        self:SetLabel('');self:SetImage(nil)\010    end\010    return addon:RegisterConditionWidget(w)\010",["kind"]="function",["line"]=13,["parameters"]={}}},["hash"]="51d83a3289eee7c6855f3fe2141d588b7dc4727f0efd333251afd96303b0b8ec"},["UI/condition_inputs.lua"]={["bindings"]={["CreateConditionEditBox"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["constructor"]="builtin:UI/condition_inputs.lua:constructor"},["callName"]="addon:CreateConditionEditBox",["code"]="\010    local w=addon:AcquireConditionWidget('RM-ConditionEditBox',function() return constructor(false) end)\010    ---@cast w RMConditionInput\010    return w\010",["description"]="Create a native text input using the condition widget contract. SetLabel, SetText, SetDisabled and SetCallback configure it; OnEnterPressed commits text. Add it to the callback parent with parent:AddChild(widget).",["kind"]="function",["line"]=131,["parameters"]={"self"},["returns"]={{["description"]="Text widget supporting label, text, pending-edit and callback methods.",["type"]="RMConditionInput"}}},["CreateConditionSlider"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["constructor"]="builtin:UI/condition_inputs.lua:constructor"},["callName"]="addon:CreateConditionSlider",["code"]="\010    local w=addon:AcquireConditionWidget('RM-ConditionSlider',function() return constructor(true) end)\010    ---@cast w RMConditionInput\010    return w\010",["description"]="Create a native numeric condition input with a slider and typed numeric field. Configure SetSliderValues, SetValue, SetIsPercent and SetCallback; OnValueChanged reports committed values. Add it with parent:AddChild(widget).",["kind"]="function",["line"]=137,["parameters"]={"self"},["returns"]={{["description"]="Numeric widget supporting slider bounds, percent display and pending-edit validation.",["type"]="RMConditionInput"}}},["constructor"]={["bindings"]={["finite"]="builtin:UI/condition_inputs.lua:finite"},["code"]="\010    local w={type=numeric and 'RM-ConditionSlider' or 'RM-ConditionEditBox',alive=false}\010    local frame=CreateFrame('Frame',nil,UIParent);w.frame=frame;frame:SetSize(220,44)\010    local caption=frame:CreateFontString(nil,'OVERLAY','GameFontHighlightSmall');w.caption=caption\010    caption:SetPoint('TOPLEFT');caption:SetPoint('TOPRIGHT');caption:SetHeight(18);caption:SetJustifyH('LEFT')\010    local input=addon:CreateWorkbenchEditBox(frame);w.editbox=input;input:SetMaxLetters(4096)\010    local slider=numeric and addon:CreateWorkbenchSlider(frame,0,100,1,140) or nil;w.slider=slider\010    local function display()\010        local value=w.value\010        if not numeric then return w.text or '' end\010        if value==nil then return '' end\010        if not finite(value) then return tostring(value) end\010        return string.format('%.6g',value*(w.isPercent and 100 or 1))..(w.isPercent and '%' or '')\010    end\010    local function parse(text)\010        text=text:match('^%s*(.-)%s*$')\010        if w.isPercent and text:sub(-1)=='%' then text=text:sub(1,-2) end\010        local value=tonumber(text)\010        if not finite(value) then return end\010        if w.isPercent then value=value/100 end\010        if value<w.minimum or value>w.maximum then return end\010        return value\010    end\010    local function paint()\010        w.setting=true;input:SetText(display());w.confirmed=input:GetText();w.pending=false\010        input:SetTextColor(1,1,1)\010        if slider then slider:SetValue(finite(w.value) and w.value or w.minimum) end\010        w.setting=false\010    end\010    local function pendingChanged() w:Fire('OnPendingChanged',w.pending) end\010    function w:SetLabel(text)\010        self.label=text or '';caption:SetText(self.label);local y=self.label~='' and -20 or 0\010        if self.label~='' then caption:Show() else caption:Hide() end\010        input:ClearAllPoints();input:SetPoint('TOPRIGHT',0,y);input:SetHeight(24)\010        if slider then\010            input:SetWidth(64);slider:ClearAllPoints();slider:SetPoint('LEFT',frame,'LEFT',0,y/2);slider:SetPoint('RIGHT',input,'LEFT',-8,0)\010        else input:SetPoint('TOPLEFT',0,y) end\010        self:SetHeight(self.label~='' and 44 or 24)\010    end\010    function w:SetText(text) self.text=text==nil and '' or tostring(text);paint() end\010    function w:GetText() return input:GetText() end\010    function w:SetValue(value) self.value=value;paint() end\010    function w:GetValue() return self.value end\010    function w:SetSliderValues(minimum,maximum,step)\010        if not finite(minimum) or not finite(maximum) or maximum<minimum or not finite(step) or step<=0 then return end\010        self.minimum,self.maximum,self.step=minimum,maximum,step\010        self.setting=true;slider:SetMinMaxValues(minimum,maximum);slider:SetValueStep(step);self.setting=false;paint()\010    end\010    function w:SetIsPercent(value) self.isPercent=value==true;paint() end\010    function w:IsPending() return self.alive and not self.disabled and self.pending==true end\010    function w:CommitPending()\010        local owner=self\010        for _=1,128 do\010            if not owner then break end\010            if owner.isQueuedForRelease then return true end\010            owner=owner.parent\010        end\010        if not self:IsPending() then return true end\010        local text=input:GetText();local value=numeric and parse(text) or text\010        if numeric and not finite(value) then input:SetTextColor(1,.35,.35);return nil end\010        local changed=numeric and value~=self.value or not numeric and text~=self.text\010        if numeric then self.value=value else self.text=text end\010        paint()\010        if changed then self:Fire(numeric and 'OnValueChanged' or 'OnEnterPressed',value) end\010        pendingChanged();return true\010    end\010    function w:SetFocus() if self.alive and not self.disabled then input:SetFocus() end end\010    function w:ClearFocus() input:ClearFocus() end\010    function w:SetMaxLetters(value) input:SetMaxLetters(value) end\010    function w:SetDisabled(value)\010        self.disabled=value==true\010        input:EnableMouse(not self.disabled);input:EnableKeyboard(not self.disabled)\010        if slider then slider:EnableMouse(not self.disabled) end\010        frame:SetAlpha(self.disabled and .45 or 1)\010        if self.disabled then paint();input:ClearFocus() end\010    end\010    function w:OnAcquire()\010        self.alive=true;self.minimum,self.maximum,self.step=0,100,1;self.isPercent=false;self.value=nil;self.text=''\010        self:SetMaxLetters(4096);self:SetWidth(220);self:SetLabel('');self:SetDisabled(false)\010        if slider then self:SetSliderValues(0,100,1) end;paint()\010    end\010    function w:OnRelease() self.alive=false;self.pending=false;input:ClearFocus() end\010    addon:SetUIScript(input,'OnTextChanged',function(_,user)\010        if w.setting or not user or not w.alive or w.disabled then return end\010        w.pending=input:GetText()~=w.confirmed\010        local valid=not numeric or parse(input:GetText())~=nil\010        input:SetTextColor(1,valid and 1 or .35,valid and 1 or .35);pendingChanged()\010    end)\010    addon:SetUIScript(input,'OnEnterPressed',function() if w.alive and not w.disabled and w:CommitPending() then input:ClearFocus() end end)\010    addon:SetUIScript(input,'OnEditFocusLost',function() if w.alive and not w.disabled and not w.isQueuedForRelease then w:CommitPending() end end)\010    addon:SetUIScript(input,'OnEscapePressed',function() if w.alive then paint();input:ClearFocus();pendingChanged() end end)\010    -- Reference popups can temporarily hide their editor. Only release\010    -- discards pending input; ordinary hiding must retain invalid blockers too.\010    addon:SetUIScript(frame,'OnHide',function() input:ClearFocus() end)\010    if slider then\010        slider:EnableMouseWheel(true)\010        addon:SetUIScript(slider,'OnValueChanged',function(_,value)\010            if w.setting or not w.alive or w.disabled or not finite(value) then return end\010            value=math.max(w.minimum,math.min(w.maximum,w.minimum+math.floor((value-w.minimum)/w.step+.5)*w.step))\010            local changed=value~=w.value;w.value=value;paint()\010            if changed then w:Fire('OnValueChanged',value) end;pendingChanged()\010        end)\010        addon:SetUIScript(slider,'OnMouseWheel',function(_,direction)\010            if w.alive and not w.disabled and direction~=0 then slider:SetValue((finite(w.value) and w.value or w.minimum)+(direction>0 and w.step or -w.step)) end\010        end)\010    end\010    ---@cast w RMConditionWidget\010    return addon:RegisterConditionWidget(w)\010",["kind"]="function",["line"]=21,["parameters"]={"numeric"}},["finite"]={["bindings"]={},["code"]=" return type(value)=='number' and value==value and value>-math.huge and value<math.huge ",["kind"]="function",["line"]=2,["parameters"]={"value"}}},["hash"]="75864ee3bc0ce320e4146dbf07284894d411a6d0b744d6a0b8cb1e866bdec864"},["UI/condition_layout.lua"]={["bindings"]={["CreateConditionGroup"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["constructor"]="builtin:UI/condition_layout.lua:constructor"},["callName"]="addon:CreateConditionGroup",["code"]="\010    local group=addon:AcquireConditionWidget('RM-ConditionGroup',constructor)\010    ---@cast group RMConditionGroup\010    return group\010",["description"]="Create a condition field container with RM-owned List, Table and responsive spell-field layouts. It accepts registered native condition widgets; add children with AddChild and attach the group to the callback parent.",["kind"]="function",["line"]=128,["parameters"]={"self"},["returns"]={{["description"]="Condition container supporting SetLayout, AddChild, SetUserData, SetWidth and DoLayout.",["type"]="RMConditionGroup"}}},["constructor"]={["bindings"]={["verticalAlignment"]="builtin:UI/condition_layout.lua:verticalAlignment"},["code"]="\010    local group={type='RM-ConditionGroup',children={}}\010    local frame=CreateFrame('Frame',nil,UIParent);group.frame=frame;group.content=frame\010    function group:OnAcquire() self.children={};self.layout='List';self.paused=false;self.layingOut=false;self:SetWidth(300);self:SetHeight(1) end\010    function group:SetLayout(layout)\010        if layout~='List' and layout~='Table' and layout~='RM-SpellField' then error('unsupported-condition-layout',0) end\010        self.layout=layout;self:DoLayout()\010    end\010    function group:PauseLayout() self.paused=true end\010    function group:ResumeLayout() self.paused=false;self:DoLayout() end\010    function group:OnWidthSet() if not self.sizing then self:DoLayout() end end\010    function group:SetWidth(width)\010        self.sizing=true;frame:SetWidth(width);frame.width=width;self.sizing=false;self:DoLayout()\010    end\010    function group:LayoutFinished(_,height) self:SetHeight(height or 1) end\010    local function validateChild(self,child,seen)\010        if not addon:IsConditionWidget(child) or not child.rmActive or child:IsReleasing() then error('foreign-or-inactive-condition-child',0) end\010        if not self.rmActive or self:IsReleasing() then error('inactive-condition-parent',0) end\010        if child.parent or seen and seen[child] then error('condition-child-already-owned',0) end\010        local current=self\010        for _=1,128 do\010            if not current then return end\010            if current==child then error('condition-widget-parent-cycle',0) end\010            current=current.parent\010        end\010        error('condition-widget-parent-cycle',0)\010    end\010    function group:AddChild(child)\010        validateChild(self,child)\010        self.children[#self.children+1]=child;child.parent=self\010        child.frame:SetParent(frame);child.frame:Show();self:DoLayout()\010    end\010    function group:AddChildren(...)\010        local seen={}\010        for i=1,select('#',...) do local child=select(i,...);validateChild(self,child,seen);seen[child]=true end\010        for i=1,select('#',...) do local child=select(i,...);self.children[#self.children+1]=child;child.parent=self;child.frame:SetParent(frame);child.frame:Show() end\010        self:DoLayout()\010    end\010    function group:ReleaseChildren()\010        local children=self.children\010        for _,child in ipairs(children) do if not addon:IsConditionWidget(child) then error('foreign-condition-child',0) end end\010        self.children={}\010        local problem\010        for _,child in ipairs(children) do local ok,why=pcall(addon.ReleaseConditionWidget,addon,child);child.parent=nil;if not ok then problem=problem or why end end\010        if problem then error(problem,0) end\010        self:DoLayout()\010    end\010    function group:DoLayout()\010        if self.paused or self.layingOut or self.isQueuedForRelease then return end\010        self.layingOut=true\010        local ok,why=pcall(function()\010        local width=math.max(1,frame:GetWidth() or 300);local padding=self:GetUserData('padding')\010        padding=type(padding)=='number' and padding==padding and math.max(0,math.min(64,padding)) or 0\010        width=math.max(1,width-padding*2);local y=padding;local gap=4\010        local settings=self:GetUserData('table');local columns=self.layout=='Table' and settings and settings.columns\010        if self.layout=='RM-SpellField' then\010            y=addon:LayoutWorkbenchSpellGroup(frame,self.children) or 0\010        else\010            local widths\010            if columns and #columns>0 then\010                widths={};local fixed,weight=gap*(#columns-1),0\010                for i,column in ipairs(columns) do\010                    if type(column)=='number' and column<=0 then\010                        local measured=0\010                        for index=i,#self.children,#columns do local child=self.children[index];local size=type(child.width)=='number' and child.width or child.frame and child.frame:GetWidth() or 0;measured=math.max(measured,size) end\010                        widths[i]=measured;fixed=fixed+measured\010                    elseif type(column)=='number' and column<1 then widths[i]=width*column;fixed=fixed+widths[i]\010                    elseif type(column)=='number' and column>=10 then widths[i]=column;fixed=fixed+column\010                    else weight=weight+(type(column)=='number' and column or 1) end\010                end\010                for i,column in ipairs(columns) do if not widths[i] then widths[i]=math.max(1,(width-fixed)*(type(column)=='number' and column or 1)/math.max(1,weight)) end end\010            end\010            local x,rowHeight,column=padding,0,1\010            local row={}\010            local function finishRow()\010                for _,entry in ipairs(row) do\010                    entry.control:ClearAllPoints();entry.control:SetPoint('TOPLEFT',frame,'TOPLEFT',entry.x,-y-(rowHeight-entry.height)*entry.align)\010                end\010                y=y+rowHeight+gap;x,rowHeight,column=padding,0,1;row={}\010            end\010            for _,child in ipairs(self.children) do\010                local control=child.frame\010                if control then\010                    local childWidth=widths and widths[column] or (child.width=='fill' or child.fullWidth) and width or child.width=='relative' and width*(child.relWidth or 1) or child.width or control:GetWidth()\010                    if type(childWidth)~='number' then childWidth=width end\010                    child:SetWidth(math.max(1,childWidth));if child.DoLayout and child.type~='RM-ConditionGroup' then child:DoLayout() end\010                    local height=control:GetHeight() or child.height or 0;rowHeight=math.max(rowHeight,height)\010                    local cell=child:GetUserData('cell')\010                    row[#row+1]={control=control,x=x,height=height,align=widths and cell and verticalAlignment(cell.alignV) or 0}\010                    if widths and column<#widths then x=x+widths[column]+gap;column=column+1\010                    else finishRow() end\010                end\010            end\010            if #row>0 then finishRow() end\010            y=math.max(1,y-gap+padding)\010        end\010        self:LayoutFinished(width,y)\010        end)\010        self.layingOut=false\010        if not ok then self.paused=false;error(why,0) end\010        if self.parent and self.parent.DoLayout then self.parent:DoLayout() end\010    end\010    ---@cast group RMConditionWidget\010    return addon:RegisterConditionWidget(group)\010",["kind"]="function",["line"]=22,["parameters"]={}},["verticalAlignment"]={["bindings"]={},["code"]="\010    if value==nil then return 0 end\010    if type(value)~='string' then return nil end\010    value=value:lower()\010    if value=='start' or value:sub(1,3)=='top' then return 0 end\010    if value=='end' or value:sub(1,6)=='bottom' then return 1 end\010    if value=='middle' or value:sub(1,6)=='center' then return .5 end\010",["kind"]="function",["line"]=14,["parameters"]={"value"}}},["hash"]="e305f2b30658a825651518e19132ba45402910b179582fb49df8cf26bc5ddf0e"},["UI/condition_position.lua"]={["bindings"]={["CreateConditionPositionPad"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["constructor"]="builtin:UI/condition_position.lua:constructor"},["callName"]="addon:CreateConditionPositionPad",["code"]="\010    return self:AcquireConditionWidget('RM-ConditionPositionPad',constructor)\010",["description"]="Create a native position pad using the shared directional controls. OnOffsetChanged reports horizontal and vertical direction, whether Center was pressed, and the increment (one, or ten with Shift). SetDisabled controls interaction; add the pad to the supplied parent.",["kind"]="function",["line"]=34,["parameters"]={"self"},["returns"]={{["description"]="Native directional pad with center reset and lease-protected callbacks.",["type"]="RMConditionPositionPad"}}},["constructor"]={["bindings"]={},["code"]="\010    local w={type='RM-ConditionPositionPad',disabled=false}\010    local frame=CreateFrame('Frame',nil,UIParent);w.frame=frame\010    local pad=addon:CreateWorkbenchPositionPad(frame);w.pad=pad;pad:SetPoint('TOPLEFT')\010    local clicks={}\010    for name,button in pairs(pad.buttons) do clicks[name]=button:GetScript('OnClick') end\010    function w:SetDisabled(value)\010        self.disabled=value==true\010        for _,button in pairs(pad.buttons) do if self.disabled then button:Disable() else button:Enable() end end\010    end\010    function w:OnAcquire()\010        self:SetWidth(48);self:SetHeight(48);self:SetDisabled(false)\010        local lease=self.rmLease\010        local function live() return w.rmActive and w.rmLease==lease and not w.disabled and not w:IsReleasing() end\010        pad:Bind(function(dx,dy,center,amount) w:Fire('OnOffsetChanged',dx,dy,center,amount) end,live,false)\010        for name,button in pairs(pad.buttons) do\010            local click=clicks[name]\010            addon:SetUIScript(button,'OnClick',function(...) if live() then return click(...) end end)\010        end\010    end\010    function w:OnRelease()\010        pad:Bind(nil,nil,true);self.disabled=true\010    end\010    return addon:RegisterConditionWidget(w)\010",["kind"]="function",["line"]=8,["parameters"]={}}},["hash"]="d777c1d4e2762c067462ad47c6db9c220bca261e8b08c71d958fe6d3e90bb66c"},["UI/condition_unit.lua"]={["bindings"]={["Widget_UnitWidget"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"},{["description"]="Condition value record updated when a unit is chosen.",["name"]="value",["type"]="table"},{["description"]="Unit key-to-display-name map shown in the selector.",["name"]="units",["type"]="table"},{["description"]="Callback invoked after changing the selected unit.",["name"]="update",["type"]="function"},{["description"]="Value record field to edit; defaults to unit.",["name"]="field",["type"]="string | nil"}},["bindingID"]="builtin:Conditions/common.lua:Widget_UnitWidget",["bindings"]={},["callName"]="addon:Widget_UnitWidget",["code"]="\010    if field == nil then\010        field = \"unit\"\010    end\010    local unit = addon:CreateConditionDropdown()\010    unit:SetLabel(L[\"Unit\"])\010    unit:SetCallback(\"OnValueChanged\", function(_, _, v)\010        value[field] = v\010        update()\010    end)\010    unit:SetDisabled(value.disabled)\010    unit.configure = function()\010        unit:SetList(units, addon.keys(units))\010        unit:SetValue(value[field])\010    end\010\010    return unit\010",["description"]="Create a configured unit selector bound to a condition value record. Returns the widget for the caller to add to the condition callback parent.",["kind"]="function",["line"]=5,["namespace"]="Conditions.common",["parameters"]={"self","value","units","update","field"},["returns"]={{["description"]="Configured unit selector; add it with parent:AddChild(widget).",["type"]="RMConditionSelector"}}}},["hash"]="0e6b96a398fbab3dfdcc8b9af43cdec877582738621aacaf60a09e31d5c09e02"},["UI/selector.lua"]={["bindings"]={["CreateConditionDropdown"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["selectorWidget"]="builtin:UI/selector.lua:selectorWidget"},["callName"]="addon:CreateConditionDropdown",["code"]="\010    local w=addon:AcquireConditionWidget('RM-Selector',selectorWidget)\010    ---@cast w RMConditionSelector\010    return w\010",["description"]="Create a native condition selector. SetList accepts key-to-label or key-to-entry maps; SetValue selects a key and OnValueChanged reports changes. Add it with parent:AddChild(widget).",["kind"]="function",["line"]=162,["parameters"]={"self"},["returns"]={{["description"]="Selector widget supporting SetList, SetValue, SetLabel, SetDisabled and callbacks.",["type"]="RMConditionSelector"}}},["selectorWidget"]={["bindings"]={},["code"]="\010    local w={type='RM-Selector',list={},order={},disabled=false}\010    local frame=CreateFrame('Frame',nil,UIParent);w.frame=frame;frame:SetSize(220,44)\010    local caption=frame:CreateFontString(nil,'OVERLAY','GameFontHighlightSmall');w.caption=caption;caption:SetPoint('TOPLEFT',0,0);caption:SetPoint('TOPRIGHT',0,0);caption:SetHeight(18);caption:SetJustifyH('LEFT')\010    local button=addon:CreateWorkbenchLabeledIconButton(frame,'chevron-down','',220);w.button=button;button:SetPoint('TOPLEFT',0,-20);button:SetPoint('TOPRIGHT',0,-20)\010    local popup=addon:CreateWorkbenchSelector();w.selector=popup\010    function w:OnAcquire() self.alive=true;self.list={};self.order={};self:SetDisabled(false);self:SetLabel('');self:SetValue(nil);self:SetWidth(220);self:SetHeight(44) end\010    function w:OnRelease() self.alive=false;popup:Release();self.list={};self.order={};self.value=nil end\010    function w:SetLabel(text) caption:SetText(text or '');local has=text and text~='';if has then caption:Show() else caption:Hide() end;button:ClearAllPoints();button:SetPoint('TOPLEFT',0,has and -20 or 0);button:SetPoint('TOPRIGHT',0,has and -20 or 0);self:SetHeight(has and 44 or 24) end\010    function w:SetText(text) button:SetText(text or L['Select']);addon:AlignWorkbenchTextLeft(button,26) end\010    function w:SetValue(value) self.value=value;local entry=self.list[value];if type(entry)=='table' then addon:PaintSelectorSelection(button,entry,entry.text) else self:SetText(entry);if button.valueIcon then button.valueIcon:Hide() end end end\010    function w:GetValue() return self.value end\010    function w:SetList(values,order)\010        self.list=values or {};self.order={};if order then for _,id in ipairs(order) do self.order[#self.order+1]=id end else for id in pairs(self.list) do self.order[#self.order+1]=id end;table.sort(self.order,function(a,b) return tostring(type(self.list[a])=='table' and self.list[a].text or self.list[a])<tostring(type(self.list[b])=='table' and self.list[b].text or self.list[b]) end) end;self:SetValue(self.value)\010    end\010    function w:SetDisabled(value) self.disabled=value==true;if self.disabled then button:Disable();popup:Hide() else button:Enable() end end\010    function w:ClearFocus() popup:Hide() end\010    addon:SetUIScript(button,'OnClick',function()\010        if not w.alive or w.disabled then return end\010        if popup.frame:IsShown() then popup:Hide();return end\010        local entries={};for _,id in ipairs(w.order) do local item=w.list[id];entries[#entries+1]={value=id,text=type(item)=='table' and item.text or item,icon=type(item)=='table' and item.icon or nil} end\010        local lifetime=w.userdata\010        popup:Open(button,entries,w.value,function(value) if value~=w.value then w:SetValue(value);w:Fire('OnValueChanged',value) end end,function() return w.alive and w.userdata==lifetime and not w.disabled end)\010    end)\010    addon:SetUIScript(frame,'OnHide',function() popup:Hide() end)\010    ---@cast w RMConditionWidget\010    return addon:RegisterConditionWidget(w)\010",["kind"]="function",["line"]=133,["parameters"]={}}},["hash"]="aea2da6933f09c74d948c44be4a5a37c2961e1f1451500aa36a9f4700feab010"},["utils.lua"]={["bindings"]={["_G"]={["kind"]="value"},["color"]={["kind"]="value"},["string"]={["kind"]="value"}},["hash"]="9327d3a00ff48b94ba24c69ef9f1a2a19e81ef916503210ace1c66a422ee39ed"}}}
